export const BUNDLED_ARTICLES: BundledArticle[] = [{"slug":"who-is-naguib-mahfouz-ar","section":"people","language":"ar","title":"نجيب محفوظ: حياته وأعماله ومكانته الأدبية","summary":"ملف سيرة موثق عن الأديب المصري نجيب محفوظ، سياقه الثقافي ومسيرته الأدبية وجائزة نوبل، مع التمييز بين الوقائع والتفسير النقدي.","body":"## النشأة والبيئة الثقافية\n\nوُلد نجيب محفوظ في القاهرة عام 1911، ونشأ في مدينة كانت أحياؤها الشعبية وأسواقها ومؤسساتها جزءًا أساسيًا من الحياة اليومية. أصبحت القاهرة لاحقًا أكثر من مجرد خلفية في أعماله؛ فهي فضاء تتقاطع فيه تحولات المجتمع والأسرة والعمل والسياسة. وتساعد معرفة هذا السياق على فهم سبب حضور الشوارع والمقاهي والبيوت والعلاقات بين الأجيال في كثير من رواياته، من دون افتراض أن كل شخصية روائية تمثل شخصًا حقيقيًا بعينه.\n\n## المسار الأدبي وتطور الكتابة\n\nبدأ محفوظ مسيرته الأدبية في النصف الأول من القرن العشرين، وكتب الرواية والقصة على امتداد عقود. تتنوع أعماله بين روايات تستلهم التاريخ المصري القديم وأعمال تتناول الحياة الاجتماعية الحديثة، ثم تجارب رمزية وفلسفية أكثر تعقيدًا. لا تختصر هذه المراحل في أسلوب واحد ثابت؛ فقد تغيّرت أدواته وموضوعاته مع تغير أسئلته الأدبية ومع التحولات التي شهدها المجتمع المصري.\n\n## القاهرة في الروايات\n\nتظهر المدينة في روايات محفوظ بوصفها شبكة من العلاقات والاختيارات والضغوط الاجتماعية، لا مجرد مكان للأحداث. وتتيح قراءة أعمال مثل الثلاثية القاهرية تتبع أثر الزمن في الأسرة والتعليم والعمل ومكانة المرأة والعلاقة بين الأجيال. ومع ذلك، فإن الشخصيات والأحداث الروائية بناء فني؛ لذلك ينبغي التمييز بين العالم المتخيل والوقائع التاريخية التي يمكن التحقق منها من مصادر مستقلة.\n\n## جائزة نوبل ومكانته\n\nحصل محفوظ على جائزة نوبل في الأدب عام 1988، وكان أول كاتب عربي يفوز بها. ويُعد هذا التكريم محطة بارزة في تلقي الأدب العربي عالميًا، لكنه لا يغني عن قراءة الأعمال نفسها أو عن دراسة تنوع الأدب العربي وتاريخه. وتوفر صفحة نوبل المرجعية معلومات أساسية عن الجائزة، بينما تساعد المراجع الأدبية المستقلة على وضع مسيرته ضمن تاريخ الرواية العربية الحديثة.\n\n## كيف نقرأ إرثه اليوم؟\n\nيمكن الاقتراب من محفوظ بقراءة عمل كامل، ثم مقارنة موضوعاته بالسياق التاريخي والنقدي الذي كُتب فيه. من المفيد كذلك الرجوع إلى الطبعات الموثوقة والدراسات الأكاديمية بدل الاعتماد على اقتباسات متداولة أو ملخصات بلا إحالات. وتظل بعض الأحكام حول دلالات رواياته تفسيرات نقدية قابلة للنقاش، وليست حقائق سِيَرية. هذا الملف يقدم مدخلًا موثقًا، ويفصل بين المعلومات القابلة للتحقق والقراءة الأدبية التي تحتاج إلى حجة وسياق.","sources":[{"title":"Naguib Mahfouz – Facts","publisher":"Nobel Prize","url":"https://www.nobelprize.org/prizes/literature/1988/mahfouz/facts/"},{"title":"Naguib Mahfouz","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/biography/Naguib-Mahfouz"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Naguib%20Mahfouz%20HR.jpg?width=1200","imageAlt":"نجيب محفوظ","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"who-is-naguib-mahfouz-en","section":"people","language":"en","title":"Naguib Mahfouz: life, work and literary legacy","summary":"A sourced profile of Egyptian novelist Naguib Mahfouz, his cultural context, literary career and Nobel Prize, distinguishing verifiable facts from critical interpretation.","body":"## Early life and cultural setting\n\nNaguib Mahfouz was born in Cairo in 1911. The city’s neighbourhoods, markets, cafés, homes and public institutions later became a defining setting for much of his fiction. Cairo is more than a backdrop in his novels: it is a place where family life, work, class, politics and generational change intersect. This context helps explain the recurring importance of streets and everyday social relationships in his writing, without assuming that every fictional character corresponds to a particular real person.\n\n## Literary career and changing styles\n\nMahfouz wrote novels and short fiction over several decades. His work ranges from historical novels inspired by ancient Egypt to stories of modern urban life and later works that use symbolic and philosophical techniques. These phases should not be reduced to one unchanging style. His subjects and narrative methods developed alongside his own artistic questions and the social changes taking place in Egypt.\n\n## Cairo as a literary world\n\nIn Mahfouz’s fiction, Cairo functions as a network of relationships, choices and social pressures, rather than merely a location for events. Reading works such as the Cairo Trilogy allows readers to follow changes in family structures, education, employment, women’s roles and relations between generations. Fictional characters and events remain artistic constructions, however, and should be distinguished from historical claims that can be checked independently.\n\n## The Nobel Prize and international recognition\n\nMahfouz received the Nobel Prize in Literature in 1988 and became the first Arabic-language writer to receive it. The award was an important moment in the international reception of Arabic literature, but it does not replace reading his work or studying the breadth of Arabic literary history. The Nobel Foundation provides a primary reference for the award, while independent literary reference works help place his career within the development of the modern Arabic novel.\n\n## Reading his legacy today\n\nA useful approach is to read a complete work and then compare its themes with reliable historical and critical context. Readers should consult reputable editions and scholarly studies rather than circulating quotations or summaries without references. Interpretations of a novel’s meaning are critical arguments open to discussion, not biographical facts. This profile provides a sourced introduction and distinguishes verifiable information from literary interpretation, which requires evidence and context.","sources":[{"title":"Naguib Mahfouz – Facts","publisher":"Nobel Prize","url":"https://www.nobelprize.org/prizes/literature/1988/mahfouz/facts/"},{"title":"Naguib Mahfouz","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/biography/Naguib-Mahfouz"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Naguib%20Mahfouz%20HR.jpg?width=1200","imageAlt":"Naguib Mahfouz","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"what-is-inflation-ar","section":"economy","language":"ar","title":"ما هو التضخم؟ شرح مبسط ومتكامل","summary":"تعريف التضخم، كيف يُقاس، لماذا يحدث، وكيف يؤثر في القوة الشرائية.","body":"التضخم هو ارتفاع عام ومستمر نسبيًا في مستوى أسعار السلع والخدمات، ما يعني أن وحدة النقد تشتري كمية أقل من السلع عندما ترتفع الأسعار. لفهم التضخم بدقة يجب النظر إلى معدل التغير في مؤشر الأسعار، وليس إلى ارتفاع سعر سلعة واحدة فقط.","sources":[{"title":"Inflation","publisher":"International Monetary Fund","url":"https://www.imf.org/en/Topics/inflation"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/economy.svg","imageAlt":"ما هو التضخم؟ شرح مبسط ومتكامل","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"what-is-inflation-en","section":"economy","language":"en","title":"What is inflation? A clear explanation","summary":"What inflation means, how it is measured, why it happens and how it affects purchasing power.","body":"Inflation is a sustained increase in the general level of prices for goods and services. A single price increase is not enough to describe economy-wide inflation; the rate is assessed using broad price measures over time.","sources":[{"title":"Inflation","publisher":"International Monetary Fund","url":"https://www.imf.org/en/Topics/inflation"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/economy.svg","imageAlt":"What is inflation? A clear explanation","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"how-ai-works-ar","section":"technology","language":"ar","title":"كيف يعمل الذكاء الاصطناعي التوليدي؟","summary":"شرح مبسط من البيانات والتدريب إلى التنبؤ بالنص أو الصورة، مع حدود الدقة.","body":"الذكاء الاصطناعي التوليدي يعتمد على نماذج تتعلم أنماطًا من بيانات تدريب ثم تنتج مخرجات جديدة بناءً على المدخلات. جودة النتيجة تعتمد على النموذج والبيانات والسياق، لذلك لا ينبغي اعتبار كل مخرجات النموذج حقيقة دون تحقق.","sources":[{"title":"Generative AI","publisher":"NIST","url":"https://www.nist.gov/artificial-intelligence"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/technology.svg","imageAlt":"كيف يعمل الذكاء الاصطناعي التوليدي؟","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"how-ai-works-en","section":"technology","language":"en","title":"How generative AI works","summary":"From training data and learned patterns to generated text or images, including important limits.","body":"Generative AI models learn patterns from training data and produce new outputs conditioned on a prompt or other input. Their outputs can be useful while still containing errors, so important claims should be checked against reliable evidence.","sources":[{"title":"Artificial Intelligence","publisher":"NIST","url":"https://www.nist.gov/artificial-intelligence"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/technology.svg","imageAlt":"How generative AI works","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"why-sky-blue-ar","section":"science","language":"ar","title":"لماذا السماء زرقاء؟","summary":"شرح مبسط لتشتت الضوء في الغلاف الجوي ولماذا يغلب اللون الأزرق نهارًا.","body":"ضوء الشمس يحتوي أطوالًا موجية متعددة. جزيئات الغلاف الجوي تشتت الأطوال الموجية الأقصر بكفاءة أكبر من الأطول، لذلك يصل الضوء الأزرق المتشتت من اتجاهات كثيرة إلى أعيننا أثناء النهار.","sources":[{"title":"Why Is the Sky Blue?","publisher":"NASA","url":"https://science.nasa.gov/earth/earth-observatory/why-is-the-sky-blue/"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/science.svg","imageAlt":"لماذا السماء زرقاء؟","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"why-sky-blue-en","section":"science","language":"en","title":"Why is the sky blue?","summary":"A clear explanation of atmospheric scattering and the blue appearance of the daytime sky.","body":"Sunlight contains many wavelengths. Molecules in the atmosphere scatter shorter wavelengths more strongly than longer wavelengths, so scattered blue light reaches our eyes from many directions during the day.","sources":[{"title":"Why Is the Sky Blue?","publisher":"NASA","url":"https://science.nasa.gov/earth/earth-observatory/why-is-the-sky-blue/"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/science.svg","imageAlt":"Why is the sky blue?","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"what-is-public-health-ar","section":"health","language":"ar","title":"كيف نقيّم المعلومة الصحية؟","summary":"قواعد عملية للتمييز بين المعلومة الطبية الموثوقة والادعاء غير المدعوم.","body":"المعلومة الصحية الجيدة توضح الدليل وحدوده، وتفرق بين دراسة واحدة والإجماع العلمي، وتذكر متى يلزم الرجوع إلى مختص. لا ينبغي استخدام صفحة معلومات عامة بدل التشخيص أو العلاج الشخصي.","sources":[{"title":"Health Topics","publisher":"World Health Organization","url":"https://www.who.int/health-topics"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/health.svg","imageAlt":"كيف نقيّم المعلومة الصحية؟","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"what-is-public-health-en","section":"health","language":"en","title":"How to evaluate health information","summary":"Practical rules for distinguishing reliable health evidence from unsupported claims.","body":"Reliable health information states what the evidence shows and what it does not show. It distinguishes a single study from a broader body of evidence and makes clear when personal medical advice requires a qualified professional.","sources":[{"title":"Health Topics","publisher":"World Health Organization","url":"https://www.who.int/health-topics"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/health.svg","imageAlt":"How to evaluate health information","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"world-war-two-overview-ar","section":"history","language":"ar","title":"الحرب العالمية الثانية: خط زمني مختصر","summary":"مدخل منظم إلى أهم مراحل الحرب وأطرافها ونهايتها.","body":"بدأت الحرب العالمية الثانية في أوروبا عام 1939 ثم اتسع نطاقها عالميًا. من أبرز محطاتها توسع دول المحور، دخول الولايات المتحدة بعد هجوم بيرل هاربر، تقدم الحلفاء، وإنهاء الحرب في أوروبا وآسيا عام 1945.","sources":[{"title":"World War II","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/World-War-II"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/history.svg","imageAlt":"الحرب العالمية الثانية: خط زمني مختصر","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"world-war-two-overview-en","section":"history","language":"en","title":"World War II: a concise timeline","summary":"A structured introduction to the major phases, participants and end of the Second World War.","body":"World War II began in Europe in 1939 and expanded into a global conflict. Major phases included Axis expansion, the United States entering the war after Pearl Harbor, Allied advances, and the end of the war in Europe and Asia in 1945.","sources":[{"title":"World War II","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/World-War-II"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/history.svg","imageAlt":"World War II: a concise timeline","createdAt":"2026-10-06T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z","status":"PUBLISHED","fallbackEvidence":"source_only"},{"slug":"trends-verify-social-media-trends-ar","section":"trends","language":"ar","title":"كيف نتحقق من اتجاهات مواقع التواصل الاجتماعي؟","summary":"منهج عملي لفهم الاتجاهات الرقمية والتمييز بين الانتشار الحقيقي والضجيج المؤقت، مع الاعتماد على البيانات والسياق والمصادر المستقلة.","body":"## الفكرة الأساسية\n\nقد يبدو موضوع ما واسع الانتشار لأن منشورات كثيرة تتحدث عنه خلال فترة قصيرة، لكن كثرة المنشورات وحدها لا تثبت أن الرأي عام أو أن الاتجاه يمثل المجتمع كله. فقد تكون العينة منحازة إلى منصة واحدة، أو إلى فئة عمرية أو بلد معين، أو قد تكون بعض المنشورات مكررة أو منسقة ضمن حملة. لذلك ينبغي التعامل مع الاتجاه الرقمي باعتباره إشارة تحتاج إلى اختبار، لا حقيقة مكتملة بمجرد ظهورها في صفحة الأكثر تداولًا.\n\n## ما الذي نقيسه؟\n\nيجب أولًا تحديد المؤشر المقصود: عدد المنشورات، أو عدد الحسابات الفريدة، أو مرات المشاهدة، أو التفاعل، أو تغير الاهتمام عبر الزمن. هذه المقاييس ليست مترادفة. فقد يرتفع عدد المشاهدات بسبب مقطع واحد واسع الانتشار، بينما يظل عدد المشاركين الفعليين محدودًا. كما أن ارتفاع التفاعل لا يوضح وحده إن كان التفاعل مؤيدًا أم معارضًا، ولا يكشف بالضرورة عن سبب اهتمام الناس بالموضوع.\n\n## حدد النطاق الزمني والجغرافي\n\nالاتجاه الذي يظهر خلال ساعة قد يختفي في اليوم التالي، بينما قد يستمر اتجاه آخر أسابيع. وينبغي مقارنة فترات زمنية متشابهة، وتحديد اللغة والمنطقة والمنصة التي جُمعت منها البيانات. لا يصح تعميم ما يحدث في منصة معينة على كل مستخدمي الإنترنت، ولا تعميم ما يظهر في بلد على سكان بلدان أخرى. وإذا تغيرت طريقة القياس أو خوارزمية المنصة، فقد يبدو التغير أكبر أو أصغر من الواقع.\n\n## افحص جودة البيانات\n\nقبل تفسير الأرقام، اسأل عن طريقة جمعها، ومدى تكرار الحسابات، واحتمال وجود حسابات آلية، وما إذا كانت البيانات تشمل المنشورات المحذوفة أو الخاصة. وتفيد مقارنة أكثر من مصدر مستقل في معرفة ما إذا كان الاهتمام يظهر خارج المنصة الأولى. كما ينبغي التمييز بين بيانات المنصة نفسها، وتحليلات شركة تجارية، واستطلاع رأي مصمم بعينة معلومة؛ فلكل نوع حدود مختلفة.\n\n## افصل بين الانتشار والرأي العام\n\nالمحتوى الأكثر تداولًا لا يمثل بالضرورة رأي الأغلبية. فقد تكون الفئات الأكثر نشاطًا على الإنترنت أصغر من أن تمثل المجتمع، وقد يدفع الغضب أو الفكاهة الناس إلى المشاركة دون تبني الرسالة. لقياس الرأي العام بصورة أفضل، نحتاج إلى استطلاعات موثقة ذات عينة معلومة وأسئلة واضحة، ثم نقارن نتائجها بالإشارات الرقمية بدل أن نستبدل أحد النوعين بالآخر.\n\n## كيف نكتب خلاصة مسؤولة؟\n\nتذكر الخلاصة الجيدة الموضوع، والمنصة، والفترة، والمؤشر، والمصدر، وما لا تسمح البيانات باستنتاجه. استخدم عبارات مثل «ارتفع عدد المنشورات المرصودة في هذه المنصة خلال هذه الفترة» بدلًا من «الجميع يتحدث عن الموضوع». وإذا كانت البيانات ناقصة، فاذكر ذلك صراحة. لا تستنتج أن اتجاهًا ما منظم أو عفوي أو مؤيد أو معارض من دون دليل مناسب.\n\n## مصادر وحدود\n\nتقدم مراكز الأبحاث المتخصصة بيانات عن استخدام المنصات، بينما يدرس تقرير الأخبار الرقمية التابع لمعهد رويترز أنماط استهلاك الأخبار عبر البلدان. تساعد هذه المصادر على فهم المنهج والسياق، لكنها لا تثبت تلقائيًا صحة كل ادعاء متداول. يجب الرجوع إلى تاريخ كل تقرير وتعريفاته، وعدم نقل رقم من سنة أو بلد إلى سياق مختلف دون توضيح.","sources":[{"title":"Social Media Fact Sheet","publisher":"Pew Research Center","url":"https://www.pewresearch.org/internet/fact-sheet/social-media/"},{"title":"Digital News Report","publisher":"Reuters Institute for the Study of Journalism","url":"https://reutersinstitute.politics.ox.ac.uk/digital-news-report/2025"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Social_media_icons_%28rubin-Social-media-icons-2x%29.jpg?width=1200","imageAlt":"أيقونات منصات التواصل الاجتماعي","createdAt":"2026-10-10T04:20:00Z","updatedAt":"2026-10-10T04:20:00Z","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"trends-read-public-opinion-polls-ar","section":"trends","language":"ar","title":"كيف نقرأ استطلاعات الرأي العام؟","summary":"شرح لكيفية فهم نتائج الاستطلاعات وحدودها، من حجم العينة وصياغة السؤال إلى هامش الخطأ وتوقيت جمع البيانات.","body":"## لماذا نحتاج إلى الاستطلاعات؟\n\nيساعد استطلاع الرأي على تقدير مواقف مجموعة سكانية من خلال سؤال عينة منها بطريقة منظمة. لكنه ليس تعدادًا كاملًا لكل فرد، ولا يضمن أن تكون النتيجة صحيحة لمجرد نشرها في رسم بياني. تعتمد جودة الاستطلاع على من شملهم، وكيف اختيروا، وما الأسئلة التي طُرحت، ومتى جُمعت الإجابات، وكيف عولجت البيانات. لذلك تبدأ القراءة المسؤولة من المنهجية، لا من الرقم الأبرز في العنوان.\n\n## من شملهم الاستطلاع؟\n\nينبغي معرفة المجتمع الذي يستهدفه الاستطلاع: جميع البالغين، أم الناخبون المحتملون، أم مستخدمو منصة معينة، أم فئة محددة من العملاء. لا يجوز تعميم نتيجة عينة من مستخدمي الإنترنت على كل السكان دون مبرر. كما أن العينة الكبيرة ليست بالضرورة عينة ممثلة؛ فإذا كانت طريقة الاختيار منحازة، فإن زيادة العدد قد تقلل التذبذب العشوائي لكنها لا تزيل الانحياز المنهجي.\n\n## حجم العينة وهامش الخطأ\n\nيؤثر حجم العينة في مقدار عدم اليقين الناتج عن اختيار عينة بدلًا من المجتمع كله، لكن هامش الخطأ التقليدي لا يغطي كل المشكلات. فهو لا يقيس وحده أثر عدم الاستجابة أو صياغة السؤال أو الأوزان الإحصائية أو اختيار المشاركين من لوحة إلكترونية. وعند مقارنة نتيجتين متقاربتين، لا ينبغي إعلان تغير حقيقي إذا كان الفرق صغيرًا ولا تدعمه المنهجية أو التحليلات المصاحبة.\n\n## صياغة السؤال وترتيبه\n\nيمكن أن تتأثر الإجابات بكلمات السؤال، والخيارات المتاحة، وترتيب الأسئلة السابقة. السؤال الذي يذكر معلومة مثيرة قبل طلب الرأي قد يعطي نتيجة مختلفة عن سؤال محايد. كما أن إجبار المشاركين على اختيار إجابة واحدة قد يخفي التردد أو تعدد المواقف. لذلك من المهم قراءة نص السؤال كاملًا، لا الاكتفاء بعنوان التقرير أو ملخصه الصحفي.\n\n## التوقيت والسياق\n\nتقيس الاستطلاعات آراء الناس في وقت محدد. وقد تتغير المواقف بعد حدث مهم أو إعلان أو نقاش عام. ينبغي مقارنة استطلاعات متقاربة في التوقيت، وتحديد ما إذا كانت تستخدم الأسئلة نفسها والعينة نفسها تقريبًا. ولا تعني نتيجة استطلاع في بلد ما أن النتيجة ستتكرر في بلد آخر تختلف فيه الظروف والسياق وطريقة جمع الإجابات.\n\n## كيف نقارن المصادر؟\n\nعند وجود نتائج متعارضة، قارن الجهة الناشرة، وتاريخ العمل الميداني، وطريقة الاختيار، وحجم العينة، ونص السؤال، والجهة التي موّلت البحث. لا يكفي عدّ العناوين المؤيدة لكل نتيجة. قد تكون الاستطلاعات قد قاست جماعات مختلفة أو طرحت أسئلة مختلفة. الأفضل عرض الاختلافات المنهجية بوضوح بدل اختيار الرقم الذي يؤيد موقفًا مسبقًا.\n\n## خلاصة مسؤولة\n\nاذكر النسبة والفئة المستهدفة وتاريخ جمع البيانات، وأشر إلى حدود الاستنتاج. استخدم «أفاد المشاركون في هذه العينة» عندما يكون ذلك أدق من «يعتقد الناس». وتذكر أن استطلاعًا واحدًا لا يثبت سبب الموقف ولا يتنبأ حتمًا بالسلوك المستقبلي. تتيح مقارنة الاستطلاعات الموثوقة فهم الاتجاهات، لكن ذلك يتطلب النظر إلى المنهج والسياق وعدم إخفاء عدم اليقين.\n\n## مصادر وحدود\n\nتشرح الجمعية الأمريكية لأبحاث الرأي العام مبادئ الممارسة المهنية، وتوفر مراكز الأبحاث أدلة عن تصميم الاستطلاعات وتحليلها. ينبغي قراءة المنهجية الأصلية كلما كانت متاحة، والانتباه إلى أن طرق جمع البيانات الرقمية قد تختلف عن المقابلات الهاتفية أو الوجاهية.","sources":[{"title":"Standards and Ethics","publisher":"American Association for Public Opinion Research","url":"https://www.aapor.org/standards-and-ethics/"},{"title":"Methods","publisher":"Pew Research Center","url":"https://www.pewresearch.org/methods/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Opinion_survey_exemple_1.jpg?width=1200","imageAlt":"مثال توضيحي على استطلاع رأي","createdAt":"2026-10-10T04:20:00Z","updatedAt":"2026-10-10T04:20:00Z","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"trends-verify-social-media-trends-en","section":"trends","language":"en","title":"How to verify social media trends","summary":"A practical method for understanding digital trends and distinguishing broad interest from temporary noise using data, context and independent sources.","body":"## The core idea\n\nA topic can appear widespread because many posts discuss it in a short period, but post volume alone does not prove that the public broadly shares a view or that a trend represents society. The sample may be concentrated on one platform, age group, language or country. Posts may also be repeated, automated or coordinated. A digital trend should therefore be treated as a signal to test, not as a complete fact simply because it appears on a trending list.\n\n## Define what is being measured\n\nStart by identifying the metric: number of posts, unique accounts, views, reactions or change in attention over time. These measures are not interchangeable. A single widely shared video can produce many views while the number of distinct participants remains small. Engagement also does not reveal whether people agree or disagree, and it does not necessarily explain why they paid attention to a topic.\n\n## Set a time and geographic scope\n\nA trend that appears for an hour may disappear the next day, while another may persist for weeks. Compare similar time windows and identify the language, region and platform from which the data were collected. Activity on one platform should not automatically be generalized to all internet users, and results from one country should not be applied to another. Changes in a platform algorithm or measurement method can also alter the apparent size of a trend.\n\n## Check data quality\n\nBefore interpreting the numbers, ask how the data were collected, whether accounts or posts were deduplicated, whether automated activity may be present, and whether deleted or private content is excluded. Comparing independent sources helps determine whether interest appears beyond the original platform. Platform analytics, commercial monitoring products and surveys with documented samples have different strengths and limitations; they should not be treated as equivalent evidence.\n\n## Separate popularity from public opinion\n\nThe most shared content does not necessarily represent the majority. The most active online groups may be too small or too specific to represent the population, and people may share content because it is funny or upsetting without endorsing its message. To measure public opinion more directly, researchers need surveys with a documented sample and clear questions. Digital signals can be compared with survey findings, but should not replace them.\n\n## Write a responsible conclusion\n\nA useful summary names the topic, platform, period, metric and source, and explains what the data cannot establish. Say that observed posts increased on a particular platform during a specified period rather than claiming that everyone is discussing the topic. If data are incomplete, state that limitation. Do not label a trend coordinated, spontaneous, supportive or hostile without suitable evidence.\n\n## Sources and limitations\n\nResearch centers publish data on platform use, while the Reuters Institute Digital News Report studies news consumption across countries. These resources help establish context and methodology, but they do not automatically verify every claim circulating online. Check the date and definitions of each report, and do not transfer a statistic from one year or country to another without explanation.","sources":[{"title":"Social Media Fact Sheet","publisher":"Pew Research Center","url":"https://www.pewresearch.org/internet/fact-sheet/social-media/"},{"title":"Digital News Report","publisher":"Reuters Institute for the Study of Journalism","url":"https://reutersinstitute.politics.ox.ac.uk/digital-news-report/2025"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Social_media_icons_%28rubin-Social-media-icons-2x%29.jpg?width=1200","imageAlt":"Social media platform icons","createdAt":"2026-10-10T04:20:00Z","updatedAt":"2026-10-10T04:20:00Z","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"trends-read-public-opinion-polls-en","section":"trends","language":"en","title":"How to read public opinion polls","summary":"A guide to interpreting survey findings and their limits, from sample selection and question wording to uncertainty and fieldwork timing.","body":"## Why polls matter\n\nA public opinion poll estimates the views of a population by asking a sample selected through a defined method. It is not a complete count of every person, and a chart does not become reliable simply because it is published. Quality depends on who was included, how participants were selected, what questions they were asked, when responses were collected and how the data were processed. Responsible reading therefore starts with methodology rather than the largest number in the headline.\n\n## Who was surveyed?\n\nIdentify the target population: all adults, likely voters, users of a particular platform or a defined group of customers. A sample of internet users cannot automatically represent every resident. A large sample is not necessarily representative; if selection is biased, increasing the number may reduce random variation but cannot remove systematic bias.\n\n## Sample size and uncertainty\n\nSample size affects the uncertainty that comes from surveying a sample rather than the full population. However, a conventional margin of sampling error does not account for every problem. It does not by itself measure nonresponse, question wording, statistical weighting or the way participants were recruited from an online panel. When two results are close, a small difference should not be described as a real change unless the methodology and accompanying analysis support that interpretation.\n\n## Wording and question order\n\nAnswers can be influenced by the words in a question, the options offered and earlier questions in the survey. A question that presents a striking claim before asking for an opinion may produce different answers from a neutral question. Requiring one choice may also hide uncertainty or mixed views. Read the complete question and response options rather than relying only on a report headline or press summary.\n\n## Timing and context\n\nPolls measure views at a particular time. Opinions may change after a major event, announcement or public debate. Compare surveys with similar fieldwork dates and check whether they use comparable questions and sampling methods. A result from one country should not be assumed to apply elsewhere, where circumstances, context and data collection may differ.\n\n## Comparing different sources\n\nWhen polls disagree, compare the publisher, fieldwork dates, recruitment method, sample size, exact wording and funding. Counting headlines on each side is not a valid way to decide which result is stronger. Surveys may measure different groups or ask different questions. A sound explanation makes those methodological differences visible instead of choosing the number that supports a prior position.\n\n## A responsible summary\n\nReport the estimate, target population and fieldwork date, and acknowledge uncertainty. Say that respondents in the sample expressed a view when that is more accurate than claiming that everyone holds it. One poll cannot establish why people think something or guarantee future behavior. Comparing well-documented surveys can reveal patterns, but only when the method and context are considered and uncertainty is not hidden.\n\n## Sources and limitations\n\nThe American Association for Public Opinion Research describes professional standards, and research centers publish guidance on survey design and analysis. Consult the original methodology whenever it is available. Digital recruitment methods may differ substantially from telephone or face-to-face interviews, so the method should be considered before comparing results.","sources":[{"title":"Standards and Ethics","publisher":"American Association for Public Opinion Research","url":"https://www.aapor.org/standards-and-ethics/"},{"title":"Methods","publisher":"Pew Research Center","url":"https://www.pewresearch.org/methods/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Opinion_survey_exemple_1.jpg?width=1200","imageAlt":"Example of an opinion survey","createdAt":"2026-10-10T04:20:00Z","updatedAt":"2026-10-10T04:20:00Z","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"health-evaluate-health-information-ar","section":"health","language":"ar","title":"كيف نقيّم المعلومات الصحية قبل الاعتماد عليها؟","summary":"خطوات عملية لفحص مصدر المعلومة الصحية وجودة الدليل وحدود التوصيات، من دون تحويل المقال العام إلى تشخيص أو علاج شخصي.","body":"## الفكرة الأساسية\nتصل المعلومات الصحية عبر مواقع الأخبار والمنصات الاجتماعية ومقاطع الفيديو والإعلانات، لكن سهولة الوصول لا تعني أن المعلومة دقيقة أو مناسبة لكل شخص. وقد تكون المعلومة صحيحة في سياق محدد ثم تُعرض خارج سياقها، أو تستند إلى دراسة أولية لا تكفي وحدها لإثبات النتيجة. لذلك يبدأ التقييم بالسؤال عن المصدر والدليل والسياق، لا بعدد المشاركات أو قوة العنوان.\n\n## من يقف وراء المعلومة؟\n\nابحث عن اسم المؤسسة أو الكاتب وخبرته وصلته بالموضوع، وتحقق من تاريخ النشر والتحديث. تشرح الجهات الصحية العامة عادةً طريقة الوصول إلى توصياتها، بينما قد تخفي الإعلانات الجهة المستفيدة من بيع منتج. لا يعني الانتماء إلى مؤسسة معروفة أن كل صفحة صحيحة تلقائيًا، لكنه يتيح الرجوع إلى سياسة التحرير والمراجع وتصحيح الأخطاء.\n\n## افحص الدليل الأصلي\n\nينبغي أن تقود المعلومة المهمة إلى دراسة أو مراجعة علمية أو إرشاد صحي واضح. اقرأ ما الذي قاسه البحث فعلًا، ومن شملهم، وما حجم العينة، وهل كانت النتيجة مرتبطة بمؤشر بديل أم بنتيجة صحية مهمة للناس. لا تثبت دراسة واحدة وحدها أن علاجًا ما يناسب الجميع، ولا يكفي عنوان صحفي لمعرفة حدود البحث أو مقدار عدم اليقين.\n\n## ميّز بين الارتباط والسببية\n\nقد يظهر ارتباط بين عاملين من دون أن يكون أحدهما سببًا للآخر؛ فقد تؤثر عوامل ثالثة في النتيجة أو تكون العينة مختلفة عن المجتمع الذي يراد تعميم النتائج عليه. كما أن النتائج التي تظهر في المختبر لا تتحول تلقائيًا إلى توصية علاجية. ابحث عن تكرار النتائج في دراسات مستقلة وعن مراجعات تجمع الأدلة وتناقش نقاط الضعف.\n\n## انتبه إلى اللغة والمصلحة التجارية\n\nتستحق العبارات المطلقة مثل «علاج مضمون» أو «نتيجة فورية» أو «السر الذي يخفيه الأطباء» حذرًا خاصًا. لا تجعل شهادة شخص واحد بديلًا عن الدليل، ولا تفترض أن المنتج طبيعي يعني أنه آمن للجميع. راجع تضارب المصالح، وميّز بين إعلان مدفوع وإرشاد صحي مستقل، وتأكد من أن الأرقام لا تُعرض من دون مقام أو مقارنة مفهومة.\n\n## متى تحتاج إلى مختص؟\n\nالمعلومات العامة تساعد على طرح أسئلة أفضل، لكنها لا تستبدل تقييم الحالة الفردية أو التشخيص أو مراجعة الأدوية. إذا تعارضت المعلومات مع توجيه طبي تلقيته، فناقش الأمر مع مختص مؤهل بدل إيقاف العلاج أو تغييره بناءً على منشور. وفي الحالات العاجلة، لا تؤخر طلب المساعدة بسبب البحث على الإنترنت.\n\n## خلاصة عملية\n\nقبل مشاركة معلومة صحية، تحقق من الناشر والتاريخ والمراجع، ثم قارنها بمصدر صحي مستقل آخر. اقرأ ما تقوله الدراسة وما لا تقوله، ولا تحول احتمالًا إلى حقيقة مؤكدة. إذا تعذر العثور على دليل واضح، فالأدق وصف المعلومة بأنها غير محسومة بدل تقديمها كنصيحة مؤكدة.\n\n## المصادر وحدودها\n\nتقدم منظمة الصحة العالمية معلومات عامة عن موضوعات الصحة، وتوفر ميدلاين بلس مواد تثقيفية للمستهلكين. تساعد هذه المراجع على بدء التحقق، لكنها لا تجعل كل ادعاء متداول صحيحًا تلقائيًا؛ ينبغي الرجوع إلى الدراسة أو الإرشاد المحدد كلما أمكن.","sources":[{"title":"Health topics","publisher":"World Health Organization","url":"https://www.who.int/health-topics"},{"title":"Health Information","publisher":"MedlinePlus","url":"https://medlineplus.gov/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Stethoscope%2C%20Laennac%20type.%20Wellcome%20M0003245.jpg?width=1200","imageAlt":"سماعة طبية تاريخية","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"health-evidence-based-medicine-ar","section":"health","language":"ar","title":"ما المقصود بالطب المبني على الدليل؟","summary":"شرح لكيفية الجمع بين نتائج الأبحاث والخبرة السريرية واحتياجات المريض، مع فهم قوة الأدلة وحدودها.","body":"## تعريف مختصر\nالطب المبني على الدليل هو استخدام أفضل الأدلة البحثية المتاحة إلى جانب الخبرة المهنية وظروف المريض وقيمه عند اتخاذ القرار الصحي. لا يعني ذلك أن رقمًا واحدًا أو دراسة منفردة تحسم كل حالة، بل أن القرار يوضح أساسه وما يزال غير مؤكد، ويُراجع عندما تظهر أدلة أفضل.\n\n## ليست كل الدراسات بالقوة نفسها\n\nتختلف الدراسات في تصميمها وقدرتها على الإجابة عن السؤال. قد تساعد التجارب العشوائية على مقارنة تدخلات محددة، بينما تكشف الدراسات الرصدية عن أنماط وارتباطات في الحياة الواقعية. وتجمع المراجعات المنهجية نتائج دراسات متعددة وفق معايير معلنة، لكنها تظل محدودة بجودة الدراسات التي شملتها ومدى تشابهها.\n\n## كيف تُقرأ النتيجة؟\n\nينبغي النظر إلى حجم الأثر لا إلى وجود فرق إحصائي فقط. اسأل عن عدد المشاركين، والمدة، والنتيجة التي قِيست، والفواصل التي تعبّر عن عدم اليقين، والآثار غير المرغوبة. وقد يبدو انخفاض نسبي كبير لافتًا بينما يكون الفرق المطلق صغيرًا؛ لذلك تحتاج الأرقام إلى سياق مفهوم قبل تحويلها إلى رسالة عامة.\n\n## الإرشادات ليست وصفة موحدة\n\nتراجع الهيئات المهنية الأدلة لتطوير إرشادات تساعد المختصين، لكن التوصية قد تختلف بحسب العمر والأمراض المصاحبة والأدوية والتفضيلات وتوفر الخدمة. لا يجوز نقل توصية مخصصة لفئة بحثية إلى كل الناس من دون فحص شروطها. كما أن الإرشادات قد تتغير حين تتراكم أدلة جديدة أو تتضح مخاطر لم تكن معروفة.\n\n## القرار المشترك\n\nيشرح المختص الخيارات المتاحة والفوائد المتوقعة والمخاطر والبدائل وما لا نعرفه، ويستطيع المريض طرح الأسئلة ومناقشة ما يناسب ظروفه. هذا لا يعني أن كل الخيارات متساوية في الدليل، بل أن المعرفة العلمية تُستخدم بشفافية ضمن قرار مسؤول يراعي الحالة الفردية.\n\n## تضارب المصالح وقابلية التكرار\n\nقد يؤثر التمويل أو انتقاء النتائج أو عدم نشر الدراسات السلبية في صورة الأدلة المتاحة. لذلك تهم مراجعة مصادر التمويل، وتسجيل الدراسات، وتكرار النتائج من فرق مستقلة. ولا ينبغي اعتبار غياب الدليل دليلًا قاطعًا على انعدام الأثر، كما لا يجوز تقديم عدم اليقين على أنه إثبات للفعالية.\n\n## خلاصة عملية\n\nابحث عن مراجعات منهجية وإرشادات محدثة، واقرأ نوع الدراسة والنتيجة التي قاستها، ثم اسأل كيف تنطبق على الشخص المعني. الطب المبني على الدليل ليس وعدًا باليقين الكامل؛ إنه طريقة منظمة لتقليل التخمين ومراجعة القرارات كلما تحسنت المعرفة.\n\n## المصادر وحدودها\n\nتتيح كوكرين مراجعات للأدلة الصحية، وتنشر هيئة نيس إرشادات وتقييمات للممارسات الصحية. تختلف نطاقات هذه المصادر وموضوعاتها، لذا يجب الرجوع إلى الوثيقة المحددة وتاريخ تحديثها بدل الاكتفاء بعنوان عام.","sources":[{"title":"Cochrane Evidence","publisher":"Cochrane","url":"https://www.cochrane.org/evidence"},{"title":"Guidance","publisher":"National Institute for Health and Care Excellence","url":"https://www.nice.org.uk/guidance"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Equipment_-_Stethoscope_--_Smart-Servier.png?width=1200","imageAlt":"رسم توضيحي لسماعة طبية","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"history-primary-sources-ar","section":"history","language":"ar","title":"كيف يستخدم المؤرخون المصادر الأولية؟","summary":"طريقة لفهم الوثائق والشهادات والصور بوصفها أدلة تحتاج إلى فحص المنشأ والسياق والمقارنة، لا حقائق مكتملة بذاتها.","body":"## ما المصدر الأولي؟\nالمصدر الأولي مادة أُنتجت في زمن الحدث أو على صلة مباشرة به، مثل رسالة أو سجل إداري أو صورة أو خريطة أو شهادة. وتختلف قيمة المصدر باختلاف السؤال التاريخي؛ فالرسالة قد تكشف ما أراد صاحبها قوله، لكنها لا تثبت وحدها أن كل ما ورد فيها حدث كما وصفه. أما الدراسة اللاحقة التي تحلل عدة مصادر فهي مصدر ثانوي بالنسبة إلى الحدث الذي تدرسه.\n\n## افحص المنشأ\n\nابدأ بمعرفة من أنشأ الوثيقة، ومتى وأين أُنتجت، ولمن وُجهت، ولماذا حُفظت. قد تكون النسخة المتاحة لاحقة للأصل أو مختصرة أو مترجمة، وقد تكون الصورة مقصوصة من إطار أوسع. يساعد فحص الفهرس والجهة الحافظة وسجل النسخ في معرفة ما إذا كان المصدر أصليًا أو نسخة أو وصفًا لاحقًا.\n\n## اقرأ السياق قبل الاقتباس\n\nلا يكفي اقتطاع جملة لشرح موقف تاريخي. ينبغي معرفة ما سبق الوثيقة وما تلاها، والظروف السياسية والاجتماعية والاقتصادية التي أحاطت بها. وقد تستخدم الكلمات نفسها بمعانٍ مختلفة عبر العصور، لذلك يحتاج تفسيرها إلى مقارنة بمصادر من الفترة ذاتها وبالدراسات المتخصصة.\n\n## اسأل عن وجهة النظر والصمت\n\nلكل مصدر زاوية وحدود. قد يعكس السجل الرسمي منظور المؤسسة التي كتبته، وقد لا تظهر فيه تجارب الفئات التي لم يكن لها وصول إلى الكتابة أو الأرشفة. غياب اسم أو صوت من الوثيقة لا يثبت أنه لم يكن موجودًا؛ فقد يكون نتيجة الانتقاء أو فقدان السجلات أو طريقة الحفظ.\n\n## قارن مصادر مستقلة\n\nتزداد الثقة عندما تتفق مواد مستقلة في نقاط أساسية، مع الانتباه إلى احتمال أن يكون مصدران قد نقلا عن أصل واحد. قارن الوثائق بالصور والخرائط والسجلات المادية والدراسات الحديثة، وسجل مواضع الاتفاق والاختلاف بدل إخفائها. إذا تعارضت الأدلة، فاشرح أسباب التعارض وحدود ما يمكن استنتاجه.\n\n## كيف نعرض النتيجة؟\n\nينبغي التمييز بين ما تقوله الوثيقة حرفيًا وما يستنتجه الباحث منها. انسب الاقتباس إلى مصدره، واذكر التاريخ والجهة الحافظة حيث تتوفر البيانات، ولا تملأ الفجوات بتفاصيل متخيلة. وقد يكون الاستنتاج الأكثر دقة هو أن الأدلة الحالية لا تحسم سؤالًا بعينه.\n\n## المصادر وحدودها\n\nتقدم مكتبة الكونغرس ومصلحة الأرشيف والسجلات الوطنية الأمريكية مواد تعليمية حول تحليل المصادر الأولية. تشرح هذه الموارد منهجًا عامًا، لكنها لا تحل محل فحص الوثيقة الأصلية أو معرفة سياقها المحلي واللغوي.","sources":[{"title":"Primary Source Sets","publisher":"Library of Congress","url":"https://www.loc.gov/classroom-materials/primary-source-sets/"},{"title":"Education","publisher":"National Archives","url":"https://www.archives.gov/education"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Thucydides_Manuscript.jpg?width=1200","imageAlt":"مخطوطة تاريخية قديمة","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"history-context-and-causation-ar","section":"history","language":"ar","title":"لماذا يغيّر السياق فهم الأحداث التاريخية؟","summary":"شرح لدور التسلسل الزمني والظروف المحيطة وتعدد الأسباب في تفسير الأحداث من دون اختزالها في سبب واحد.","body":"## الحدث لا يفسر نفسه\nقد يصف التاريخ حدثًا في تاريخ محدد، لكن فهمه يتطلب معرفة الظروف التي سبقته والقرارات التي تلتْه. فالتاريخ ليس قائمة تواريخ منفصلة؛ إنه محاولة لفهم التغير والاستمرار والعلاقات بين المؤسسات والأفراد والاقتصاد والأفكار. ولا يعني وضع الحدث في سياقه تبريره، بل يساعد على تفسير ما جعل بعض الخيارات ممكنة أو مرجحة في زمن معين.\n\n## ابنِ تسلسلًا زمنيًا\n\nيساعد ترتيب الأحداث على تمييز ما وقع قبل السبب المفترض وما جاء بعده. لكن التتابع وحده لا يثبت السببية؛ فقد يتزامن حدثان من دون علاقة مباشرة. ينبغي مقارنة أكثر من تسلسل زمني، والانتباه إلى الفترات التي لا تتوفر عنها سجلات كافية، وإلى اختلاف التقويمات أو طرق تأريخ الوثائق.\n\n## ابحث عن أسباب متعددة\n\nغالبًا ما تنتج التحولات الكبيرة عن تفاعل عوامل طويلة الأمد مع أحداث قريبة وقرارات بشرية. قد تؤثر الظروف الاقتصادية أو البيئة أو المؤسسات أو الصراعات أو الأفكار، لكن وزن كل عامل يختلف من حالة إلى أخرى. تفسير الحدث بسبب واحد قد يكون جذابًا وسهل التذكر، لكنه يخفي التعقيد ويجعل الاستنتاج أقل دقة.\n\n## قارن وجهات النظر\n\nتختلف الروايات بحسب موقع الكاتب والجهة التي حفظت المصدر والجمهور المقصود. لذلك ينبغي مقارنة روايات المشاركين والجهات الرسمية والمراقبين والباحثين اللاحقين، مع عدم افتراض أن كثرة الروايات تعني استقلالها. إذا تكررت عبارة واحدة في عدة كتب فقد يكون مصدرها رواية واحدة انتقلت بينها.\n\n## تجنب إسقاط الحاضر على الماضي\n\nتتغير معاني المفاهيم والقوانين والأدوار الاجتماعية عبر الزمن. لا يصح افتراض أن الناس في الماضي امتلكوا المعلومات أو الخيارات نفسها المتاحة اليوم، كما لا ينبغي استخدام اختلاف السياق لإعفاء الأفعال من الفحص الأخلاقي. الأفضل توضيح المعايير والقيود التي كانت قائمة آنذاك ثم فصل الوصف التاريخي عن الحكم المعاصر.\n\n## ما الذي يجعل التفسير قويًا؟\n\nالتفسير الجيد يوضح الأدلة التي يستند إليها، ويذكر الأدلة المخالفة، ويفصل بين الحقيقة والاستنتاج. كما يشرح ما الذي يمكن أن يغير الرأي، مثل العثور على وثيقة جديدة أو إعادة تقييم مصدر معروف. اليقين المطلق نادر في كثير من الأسئلة التاريخية، لكن المقارنة المنهجية تجعل بعض التفسيرات أقوى من غيرها.\n\n## المصادر وحدودها\n\nتشرح الموسوعة البريطانية مناهج البحث التاريخي، وتتيح مكتبة الكونغرس مجموعات من الوثائق الأصلية. تساعد هذه المراجع على فهم المنهج والسياق، لكن تطبيقه يتطلب الرجوع إلى المصادر المتعلقة بالحدث المحدد لا تعميم مثال واحد على كل التاريخ.","sources":[{"title":"Historical Method","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/historical-method"},{"title":"Primary Source Sets","publisher":"Library of Congress","url":"https://www.loc.gov/classroom-materials/primary-source-sets/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Polybius_Histories_Papyrus.jpg?width=1200","imageAlt":"بردية تاريخية قديمة","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"economy-inflation-purchasing-power-ar","section":"economy","language":"ar","title":"كيف يؤثر التضخم في القوة الشرائية؟","summary":"شرح للعلاقة بين ارتفاع المستوى العام للأسعار والدخل والإنفاق، وكيف تُقرأ مؤشرات التضخم وحدود المقارنات بين الأسر.","body":"## ما التضخم؟\nالتضخم هو ارتفاع مستمر في المستوى العام لأسعار السلع والخدمات خلال فترة، وليس مجرد ارتفاع سعر سلعة واحدة. قد ترتفع أسعار منتج بسبب نقص مؤقت أو تغير موسمي من دون أن يعني ذلك وحده أن الاقتصاد كله يمر بالمعدل نفسه من التضخم. لذلك تعتمد المقارنة على سلة من الأسعار ومؤشر محدد وفترة زمنية معلومة.\n\n## القوة الشرائية والدخل\n\nإذا ارتفعت الأسعار أسرع من دخل الأسرة، فإن المبلغ نفسه يشتري كمية أقل من السلع والخدمات. لكن أثر التضخم يختلف باختلاف نمط الإنفاق؛ فالأسر التي تنفق نسبة كبيرة على الغذاء أو النقل قد تشعر بارتفاع مختلف عن أسرة تنفق أكثر على خدمات أخرى. ولهذا لا تعكس نسبة عامة كل تجربة فردية بالتساوي.\n\n## كيف يُحسب المؤشر؟\n\nتجمع الجهات الإحصائية أسعار سلة محددة وتتابع تغيرها وفق منهج معلن. وتؤثر أوزان المكونات في النتيجة، لأن السلع والخدمات لا تحتل الحصة نفسها من إنفاق كل أسرة. ينبغي عند قراءة الرقم معرفة تاريخ المقارنة وما إذا كان التغير سنويًا أو شهريًا، وما إذا كان المؤشر عامًا أو يستثني مكونات معينة.\n\n## الأسباب ليست واحدة\n\nقد يرتبط التضخم بارتفاع الطلب، أو زيادة تكاليف الإنتاج والطاقة والنقل، أو تغير سعر الصرف، أو اضطراب سلاسل الإمداد، أو مزيج من هذه العوامل. ويختلف وزن كل عامل بحسب البلد والفترة. لذلك لا يكفي مؤشر واحد لإثبات السبب، وتحتاج التفسيرات إلى مقارنة بيانات الأسعار والإنتاج والأجور والسياسة النقدية والتجارة.\n\n## كيف تقارن الأسعار والأجور؟\n\nينبغي مقارنة نمو الأجور بنمو الأسعار خلال الفترة نفسها، مع التمييز بين الأجر الاسمي وما يمكن شراؤه به. كما أن المتوسط قد يخفي اختلافات كبيرة بين القطاعات والمناطق والأسر. وعند مقارنة بلدين، يجب الانتباه إلى اختلاف السلال الإحصائية والعملات والضرائب وأنماط الإنفاق.\n\n## ما الذي لا يخبرنا به الرقم وحده؟\n\nلا يحدد التضخم وحده ما إذا كانت أسرة بعينها أصبحت أفقر، ولا يشرح كل تغير في الأسعار، ولا يضمن اتجاه الأسعار في المستقبل. تساعد البيانات في وصف الاتجاه، لكن تفسير الأسباب والتنبؤ يتطلب أدلة إضافية وافتراضات واضحة. من الأفضل ذكر المؤشر والفترة والمصدر بدل استخدام الرقم خارج سياقه.\n\n## خلاصة عملية\n\nعند قراءة خبر اقتصادي، تحقق من تعريف المؤشر والفترة والسلة، وقارن الأسعار بالدخل وبمصادر مستقلة. افصل بين الملاحظة والتفسير والتوقع، ولا تعمم تجربة سلعة أو أسرة على الاقتصاد كله.\n\n## المصادر وحدودها\n\nينشر صندوق النقد الدولي مواد عن التضخم والسياسات الاقتصادية، ويوفر البنك الدولي قواعد بيانات وتحليلات للمؤشرات الاقتصادية. ينبغي الرجوع إلى بيانات البلد والفترة المحددين، لأن المتوسطات العالمية لا تصف بالضرورة ظروف كل سوق.","sources":[{"title":"Inflation","publisher":"International Monetary Fund","url":"https://www.imf.org/en/Topics/inflation"},{"title":"Inflation Database","publisher":"World Bank","url":"https://www.worldbank.org/en/research/brief/inflation-database"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Consumer_Price_Index_Graph.svg?width=1200","imageAlt":"رسم بياني لمؤشر أسعار المستهلك","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"health-evaluate-health-information-en","section":"health","language":"en","title":"How to evaluate health information","summary":"A practical method for checking the publisher, evidence quality and limits of health claims without turning general information into personal diagnosis or treatment.","body":"## The core idea\nHealth information reaches people through news sites, social platforms, videos and advertising, but easy access does not guarantee accuracy or suitability for every person. A claim may be true in a narrow context and misleading when removed from that context, or it may rely on an early study that cannot establish the conclusion on its own. Evaluation starts with the source, evidence and scope, not with a headline or number of shares.\n\n## Who produced the information?\n\nLook for the organization or author, relevant expertise, publication date and update history. Public health organizations often explain how recommendations are developed, while commercial advertising may hide the financial interest behind a product. A recognizable institution is not an automatic guarantee that every page is correct, but it gives readers a way to check editorial standards, references and corrections.\n\n## Inspect the underlying evidence\n\nImportant claims should point to a study, systematic review or clear health guideline. Ask what the research actually measured, who participated, how large the sample was, and whether the outcome was a meaningful health result or only a proxy measure. One study rarely proves that a treatment works for everyone, and a news headline cannot substitute for the study limitations or uncertainty.\n\n## Separate association from causation\n\nTwo factors may occur together without one causing the other. A third factor may affect the result, or the sample may differ from the population to which the claim is applied. Laboratory findings also do not automatically become treatment recommendations. Look for results repeated in independent studies and for reviews that compare evidence and discuss weaknesses.\n\n## Notice language and commercial interests\n\nAbsolute phrases such as “guaranteed cure,” “instant result” or “the secret doctors hide” deserve special caution. One person’s story is not a substitute for evidence, and a natural product is not automatically safe for everyone. Check conflicts of interest, distinguish advertising from independent guidance, and make sure statistics are not presented without a denominator or understandable comparison.\n\n## When to consult a professional\n\nGeneral information can help people ask better questions, but it cannot replace an individual assessment, diagnosis or medication review. If online information conflicts with advice you received, discuss it with a qualified professional instead of stopping or changing treatment based on a post. In an urgent situation, do not delay seeking help while browsing the internet.\n\n## A practical checklist\n\nBefore sharing a health claim, verify the publisher, date and references, then compare it with another independent health source. Read what the study says and what it does not say, and do not turn a possibility into a confirmed fact. If clear evidence is unavailable, describing the claim as uncertain is more accurate than presenting it as established advice.\n\n## Sources and limitations\n\nThe World Health Organization provides general information on health topics, and MedlinePlus offers consumer health information. These references are useful starting points, but they do not automatically validate every circulating claim; consult the specific study or guideline whenever possible.","sources":[{"title":"Health topics","publisher":"World Health Organization","url":"https://www.who.int/health-topics"},{"title":"Health Information","publisher":"MedlinePlus","url":"https://medlineplus.gov/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Stethoscope%2C%20Laennac%20type.%20Wellcome%20M0003245.jpg?width=1200","imageAlt":"A historical medical stethoscope","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"health-evidence-based-medicine-en","section":"health","language":"en","title":"What evidence-based medicine means","summary":"How research findings, clinical expertise and patient circumstances are combined, with attention to evidence strength and uncertainty.","body":"## A concise definition\nEvidence-based medicine uses the best available research together with professional expertise and a patient’s circumstances and values when making health decisions. It does not mean that one number or a single study settles every case. Instead, it makes the basis of a decision and its uncertainties explicit, and revises the decision when better evidence appears.\n\n## Studies have different strengths\n\nResearch designs answer different questions and have different limitations. Randomized trials can compare defined interventions, while observational studies reveal patterns and associations in real-world settings. Systematic reviews combine studies using stated methods, but their conclusions remain limited by the quality and comparability of the research they include.\n\n## Read the result, not only the headline\n\nConsider the size of an effect, not merely whether a statistical difference was detected. Ask about the number of participants, follow-up period, outcome measured, uncertainty intervals and unwanted effects. A large relative reduction can sound impressive while the absolute difference is small, so figures need context before they are turned into general messages.\n\n## Guidelines are not one-size-fits-all prescriptions\n\nProfessional bodies review evidence to produce guidance, but recommendations can depend on age, other conditions, medications, preferences and access to care. A recommendation for a research population should not automatically be applied to everyone. Guidance may also change as evidence accumulates or risks become clearer.\n\n## Shared decisions\n\nA qualified professional can explain options, expected benefits, risks, alternatives and remaining uncertainty. The patient can ask questions and discuss what fits their circumstances. This does not mean all options have equal evidence; it means scientific knowledge is used transparently within a responsible decision that considers the individual case.\n\n## Conflicts of interest and replication\n\nFunding, selective reporting and missing negative studies can distort the available evidence. Researchers therefore examine funding, study registration and whether independent teams reproduce findings. A lack of evidence is not conclusive proof that an effect does not exist, but uncertainty should never be presented as proof of effectiveness.\n\n## A practical approach\n\nLook for systematic reviews and current guidelines, read the study design and outcome, then ask how it applies to the person concerned. Evidence-based medicine is not a promise of complete certainty; it is a structured way to reduce guesswork and revisit decisions as knowledge improves.\n\n## Sources and limitations\n\nCochrane provides reviews of health evidence, while NICE publishes guidance and assessments for health practice. Their scopes differ, so consult the specific document and its update date rather than relying on a general heading.","sources":[{"title":"Cochrane Evidence","publisher":"Cochrane","url":"https://www.cochrane.org/evidence"},{"title":"Guidance","publisher":"National Institute for Health and Care Excellence","url":"https://www.nice.org.uk/guidance"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Equipment_-_Stethoscope_--_Smart-Servier.png?width=1200","imageAlt":"A medical stethoscope illustration","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"history-primary-sources-en","section":"history","language":"en","title":"How historians use primary sources","summary":"How to assess documents, testimony and images as evidence by checking provenance, context and corroboration rather than treating them as complete facts.","body":"## What is a primary source?\nA primary source was created during a period or has a direct connection to the event being studied, such as a letter, administrative record, photograph, map or testimony. Its value depends on the historical question. A letter can show what its author wanted to say, but it cannot by itself prove that every statement describes events exactly as they happened. Later research that analyzes many sources is secondary for the event it studies.\n\n## Check provenance\n\nStart by asking who created the item, when and where it was produced, for whom it was intended and why it was preserved. The available version may be a later copy, an edited extract or a translation; a photograph may have been cropped from a wider scene. Catalog records, archive descriptions and version histories help distinguish an original from a copy or later description.\n\n## Read the context before quoting\n\nA sentence taken out of context rarely explains a historical position. Learn what happened before and after the document and the political, social and economic conditions around it. Words can carry different meanings across periods, so interpretation benefits from comparison with contemporary sources and specialist scholarship.\n\n## Ask about perspective and silence\n\nEvery source has a point of view and limits. An official record may reflect the institution that produced it, and archives may underrepresent people who had less access to writing or formal record keeping. The absence of a name or voice from a document does not prove that the person or group did not exist; it may reflect selection, loss or preservation practices.\n\n## Corroborate independent sources\n\nConfidence grows when independent materials agree on key points, while researchers must check whether apparently separate accounts copied the same original. Compare documents with photographs, maps, material evidence and later studies. Record both agreement and disagreement instead of hiding conflict. When evidence differs, explain the possible reasons and the limits of the conclusion.\n\n## Present findings responsibly\n\nSeparate what a document says directly from what a researcher infers. Attribute quotations, record dates and archival references when available, and do not fill gaps with imagined details. Sometimes the most accurate conclusion is that the available evidence cannot settle a particular question.\n\n## Sources and limitations\n\nThe Library of Congress and the US National Archives provide educational materials on analyzing primary sources. These resources explain a general method, but they do not replace examination of the original item or knowledge of its local and linguistic context.","sources":[{"title":"Primary Source Sets","publisher":"Library of Congress","url":"https://www.loc.gov/classroom-materials/primary-source-sets/"},{"title":"Education","publisher":"National Archives","url":"https://www.archives.gov/education"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Thucydides_Manuscript.jpg?width=1200","imageAlt":"An ancient historical manuscript","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"history-context-and-causation-en","section":"history","language":"en","title":"Why context matters in historical interpretation","summary":"How chronology, surrounding conditions and multiple causes help explain events without reducing them to a single explanation.","body":"## Events do not explain themselves\nHistory can name an event and its date, but understanding it requires attention to the conditions that came before and decisions that followed. History is not simply a list of dates; it studies change, continuity and relationships among institutions, individuals, economies and ideas. Context does not excuse an action. It helps explain which choices were possible or likely in a particular time.\n\n## Build a chronology\n\nOrdering events helps distinguish what happened before a proposed cause from what followed it. Sequence alone, however, does not prove causation; two events may coincide without a direct relationship. Compare timelines, note periods with few surviving records, and account for differences in calendars or dating practices.\n\n## Look for multiple causes\n\nMajor changes often result from the interaction of long-term conditions with immediate events and human decisions. Economic circumstances, environment, institutions, conflict and ideas may all matter, but their relative importance varies by case. A single-cause explanation may be easy to remember, yet it can hide complexity and weaken the conclusion.\n\n## Compare perspectives\n\nAccounts differ according to the author’s position, the institution that preserved the source and the intended audience. Compare participants, official bodies, observers and later researchers without assuming that multiple accounts are independent. If several books repeat the same phrase, they may all derive from one original account.\n\n## Avoid projecting the present onto the past\n\nConcepts, laws and social roles change over time. People in the past did not necessarily have the information or choices available today. At the same time, historical context should not prevent careful ethical examination. Explain the standards and constraints of the period, then distinguish historical description from present-day judgment.\n\n## What makes an interpretation strong?\n\nA strong interpretation identifies its evidence, acknowledges contrary material and separates fact from inference. It also explains what could change the conclusion, such as a newly discovered document or a reassessment of a known source. Absolute certainty is rare in many historical questions, but methodical comparison can make some explanations stronger than others.\n\n## Sources and limitations\n\nEncyclopaedia Britannica explains historical method, while the Library of Congress provides collections of primary documents. These resources help readers understand context and method, but a specific historical claim still requires sources relevant to that event rather than generalizing from one example.","sources":[{"title":"Historical Method","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/historical-method"},{"title":"Primary Source Sets","publisher":"Library of Congress","url":"https://www.loc.gov/classroom-materials/primary-source-sets/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Polybius_Histories_Papyrus.jpg?width=1200","imageAlt":"An ancient papyrus manuscript","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"economy-inflation-purchasing-power-en","section":"economy","language":"en","title":"How inflation affects purchasing power","summary":"How rising overall prices interact with income and household spending, and how to interpret inflation measures and their limits.","body":"## What is inflation?\nInflation is a sustained increase in the general price level of goods and services over time, not merely a rise in the price of one item. A product may become more expensive because of a temporary shortage or seasonal change without that alone proving that the entire economy has the same inflation rate. Comparisons therefore rely on a defined basket of prices, a particular index and a stated period.\n\n## Purchasing power and income\n\nIf prices rise faster than a household’s income, the same amount of money buys fewer goods and services. The effect differs with spending patterns: households that devote a large share of their budget to food or transport may experience a different change from households that spend more on other services. A national average does not describe every household equally.\n\n## How is an index measured?\n\nStatistical agencies track the prices of a defined basket and calculate changes using a published method. The weights matter because goods and services do not take the same share of every household budget. When reading a figure, check the comparison period and whether the rate is monthly or annual, headline or a narrower measure.\n\n## Causes vary by period\n\nInflation can be associated with strong demand, higher production and energy costs, exchange-rate changes, supply-chain disruption or a combination of factors. Their relative importance differs by country and period. One index alone cannot prove the cause; interpretation requires comparison with data on prices, output, wages, monetary policy and trade.\n\n## Compare prices and wages carefully\n\nCompare wage growth with price growth over the same period, distinguishing nominal pay from what it can buy. An average may conceal substantial differences across sectors, regions and households. Comparing countries also requires attention to basket definitions, currencies, taxes and spending patterns.\n\n## What the number cannot tell us\n\nInflation alone does not determine whether a particular household became poorer, explain every price change or guarantee the future direction of prices. Data can describe a trend, while explanations and forecasts require additional evidence and explicit assumptions. State the index, period and source rather than using a figure without context.\n\n## A practical checklist\n\nWhen reading an economic claim, check the index definition, period and basket, and compare prices with income and independent sources. Separate observations from explanations and forecasts; do not generalize from one product or household to the whole economy.\n\n## Sources and limitations\n\nThe International Monetary Fund publishes material on inflation and economic policy, while the World Bank provides economic data and analysis. Consult the data for the specific country and period because global averages do not necessarily describe local conditions.","sources":[{"title":"Inflation","publisher":"International Monetary Fund","url":"https://www.imf.org/en/Topics/inflation"},{"title":"Inflation Database","publisher":"World Bank","url":"https://www.worldbank.org/en/research/brief/inflation-database"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Consumer_Price_Index_Graph.svg?width=1200","imageAlt":"A consumer price index graph","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"world-global-supply-chains-ar","section":"world","language":"ar","title":"كيف تعمل سلاسل الإمداد العالمية؟","summary":"شرح لكيفية انتقال المواد والسلع بين الدول، ولماذا يمكن أن يؤثر اضطراب الموانئ أو النقل أو الإنتاج في الأسعار وتوافر المنتجات.","body":"## ما المقصود بسلاسل الإمداد؟\nسلسلة الإمداد هي شبكة من الأنشطة والجهات التي تنقل المواد الخام والمكونات والسلع إلى المستهلك. وقد يبدأ المنتج في بلد، ويُصنّع جزء منه في بلد آخر، ثم يُجمع ويُخزّن ويُنقل عبر عدة موانئ ومراكز توزيع. لذلك لا تعني عبارة «صُنع في بلد» بالضرورة أن كل مكوناته أو مراحل إنتاجه جاءت من المكان نفسه.\n\n## لماذا تتجاوز الحدود؟\n\nتتخصص الشركات والمناطق في مراحل مختلفة بحسب المهارات والتكاليف والمواد المتاحة والبنية التحتية. ويسمح هذا التخصص بتوسيع الإنتاج وتبادل الخبرات، لكنه يزيد الاعتماد المتبادل. فقد يؤثر نقص مكون صغير في مصنع بعيد على إنتاج سلعة كاملة، حتى لو كانت بقية المواد متوفرة.\n\n## كيف تنتقل الصدمة؟\n\nقد ينتج الاضطراب عن إغلاق ميناء، أو تعطل قناة شحن، أو كارثة طبيعية، أو نزاع، أو تغيير تجاري، أو نقص في الطاقة. وتنتقل الآثار عبر تأخير الشحنات وارتفاع أجور النقل وزيادة مخزون الأمان وتغير قرارات الشراء. ولا تتحول كل مشكلة إلى أزمة عالمية؛ يعتمد الأثر على حجم التعطل والبدائل المتاحة ومدة استمراره.\n\n## ما دور الموانئ والبيانات؟\n\nتربط الموانئ والنقل البري والسكك الحديدية والمخازن بين المنتج والمستهلك. وتساعد بيانات الشحن والمخزون ووقت التسليم الشركات على اكتشاف التأخير، لكن الرؤية قد تكون ناقصة عندما لا تتشارك الجهات معلوماتها. وتزيد الشفافية من القدرة على الاستجابة، بينما قد يؤدي الاعتماد على مسار واحد أو مورد واحد إلى هشاشة أكبر.\n\n## الكفاءة أم المرونة؟\n\nقد يقلل المورد الأقل تكلفة النفقات في الظروف العادية، لكن الاعتماد الكامل عليه يرفع مخاطر الانقطاع. وتستخدم الشركات بدائل مثل تنويع الموردين، والاحتفاظ بمخزون مناسب، وتحديد نقاط الاختناق، واختبار خطط الطوارئ. لا يوجد تصميم واحد يناسب الجميع؛ فالموازنة تعتمد على قيمة السلعة، وسرعة تلفها، وكلفة التخزين، واحتمال التعطل.\n\n## كيف نقرأ الأخبار الاقتصادية؟\n\nعند سماع أن اضطرابًا ما سيؤثر في الأسعار، اسأل عن السلعة والمنطقة والفترة والمسار المتأثر. فالتأخير في مكون محدد لا يثبت تلقائيًا ارتفاع كل الأسعار، وقد تمتص المخزونات أو البدائل جزءًا من الأثر. ينبغي التمييز بين اضطراب وقع بالفعل، واحتمال مستقبلي، وتوقع اقتصادي مبني على افتراضات.\n\n## المصادر وحدودها\n\nيوفر البنك الدولي مواد عن التجارة والتنمية، وتتناول الأونكتاد النقل والتجارة واللوجستيات. تساعد هذه المصادر على فهم النظام العالمي، لكن تقدير أثر حادث بعينه يتطلب بيانات حديثة عن المسار والسلعة وحجم المخزون والأسعار المحلية.","sources":[{"title":"Trade","publisher":"World Bank","url":"https://www.worldbank.org/en/topic/trade"},{"title":"Transport and Trade Logistics","publisher":"UN Trade and Development (UNCTAD)","url":"https://unctad.org/topic/transport-and-trade-logistics"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Container_ship_in_Hamburg.jpg?width=1200","imageAlt":"سفينة حاويات في ميناء","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"world-climate-risks-ar","section":"world","language":"ar","title":"كيف تتجاوز مخاطر المناخ حدود الدول؟","summary":"مقدمة لفهم المخاطر المناخية عبر الحدود، من انبعاثات الغازات الدفيئة إلى الغذاء والمياه والبنية التحتية والتعاون الدولي.","body":"## لماذا تعد قضية عالمية؟\nيتأثر نظام المناخ بتراكم غازات الدفيئة في الغلاف الجوي، ولا تتوقف آثار الانبعاثات عند حدود الدولة التي صدرت منها. وقد تختلف المخاطر بين المناطق بسبب الجغرافيا والموارد والبنية التحتية والقدرة على الاستعداد، لكن الترابط في الغذاء والتجارة والهجرة والطاقة يجعل بعض الآثار عابرة للحدود.\n\n## المخاطر ليست نوعًا واحدًا\n\nتشمل المخاطر موجات الحر والفيضانات والجفاف وارتفاع مستوى البحر وتغير أنماط الأمطار، كما قد تؤثر في النظم البيئية والصحة والإنتاج الزراعي. ولا يتعرض كل مكان للخطر نفسه؛ فالنتيجة تعتمد على شدة الحدث ومدته وتكراره ومدى استعداد المجتمع والبنية التحتية للتعامل معه.\n\n## كيف تنتقل الآثار؟\n\nقد يؤدي الجفاف في منطقة منتجة إلى تغير المحاصيل والأسعار والتجارة في مناطق أخرى. وقد تتأثر الموانئ والطرق والطاقة بسبب الحرارة أو الفيضانات، فتتأخر السلع والخدمات. هذه الروابط لا تعني أن كل ارتفاع في سعر الغذاء سببه المناخ؛ ينبغي فحص الإنتاج والمخزون والنقل والسياسات والعوامل الاقتصادية الأخرى.\n\n## التخفيف والتكيف\n\nيهدف التخفيف إلى خفض انبعاثات الغازات الدفيئة أو زيادة امتصاصها، بينما يهدف التكيف إلى تقليل الضرر والاستعداد للآثار القائمة والمتوقعة. ومن أمثلتهما تحسين كفاءة الطاقة، وتطوير النقل، وحماية النظم الطبيعية، وتحسين إدارة المياه، وتحديث أنظمة الإنذار. تختلف الخيارات بحسب الموارد والظروف المحلية.\n\n## لماذا نحتاج إلى بيانات موثوقة؟\n\nتساعد القياسات طويلة الأجل والنماذج والمقارنات بين مصادر مستقلة على فصل الاتجاهات عن التذبذب الطبيعي. وينبغي توضيح الفترة والمنطقة ونوع المؤشر وعدم تقديم سيناريو مستقبلي كأنه نتيجة مؤكدة. كما يجب بيان حدود النموذج والافتراضات التي يعتمد عليها، لأن النتائج قد تختلف وفق مسار الانبعاثات والاستعداد.\n\n## التعاون بين الدول\n\nتتطلب بعض الاستجابات تنسيقًا في التمويل والبيانات والتكنولوجيا والتجارة وإدارة الكوارث. وتختلف مسؤوليات الدول وقدراتها واحتياجاتها، لذا تحتاج الاتفاقات إلى أهداف قابلة للقياس ومتابعة شفافة. لا يكفي إعلان هدف عام من دون خطط تنفيذ وقياس للتقدم والنتائج.\n\n## خلاصة مسؤولة\n\nعند قراءة خبر عن المناخ، تحقق من الجهة العلمية والفترة والمنطقة ونوع المخاطر. ميّز بين الرصد الحالي والتوقعات والسيناريوهات، ولا تنسب حادثًا منفردًا إلى تغير المناخ من دون تحليل مناسب. فهم الترابط العالمي يساعد على الاستعداد، لكنه لا يلغي الحاجة إلى أدلة محددة لكل ادعاء.\n\n## المصادر وحدودها\n\nتنشر الهيئة الحكومية الدولية المعنية بتغير المناخ تقييمات علمية، وتعرض اتفاقية الأمم المتحدة الإطارية بشأن تغير المناخ معلومات عن التعاون الدولي. يجب الرجوع إلى التقرير المحدد وتاريخ صدوره ونطاقه، لا الاكتفاء بعنوان أو ملخص مقتطع.","sources":[{"title":"Assessment Reports","publisher":"Intergovernmental Panel on Climate Change","url":"https://www.ipcc.ch/assessment-report/ar6/"},{"title":"Climate Action","publisher":"UN Climate Change","url":"https://unfccc.int/climate-action"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Climate_Change_Schematic.svg?width=1200","imageAlt":"رسم يوضح آلية الاحتباس الحراري","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"world-global-supply-chains-en","section":"world","language":"en","title":"How global supply chains work","summary":"How materials and goods move between countries, and why disruption to ports, transport or production can affect prices and availability.","body":"## What is a supply chain?\nA supply chain is a network of activities and organizations that moves raw materials, components and finished goods to consumers. A product may begin in one country, have parts made elsewhere, be assembled in another location and travel through several ports and distribution centers. A label naming one country does not mean every component or production stage came from that place.\n\n## Why do chains cross borders?\n\nCompanies and regions specialize in different stages according to skills, costs, available materials and infrastructure. Specialization can expand production and spread expertise, but it also creates interdependence. A shortage of one small component at a distant factory can interrupt production of a complete product even when other materials are available.\n\n## How can a disruption spread?\n\nDisruption may follow a closed port, blocked shipping route, natural disaster, conflict, trade change or energy shortage. Effects can travel through delayed shipments, higher freight costs, safety-stock decisions and changed purchasing plans. Not every problem becomes a global crisis; the impact depends on the scale of disruption, available alternatives and duration.\n\n## Ports, transport and information\n\nPorts, roads, railways, warehouses and distribution centers connect producers with consumers. Shipping, inventory and delivery-time data help organizations detect delays, but visibility may be incomplete when firms do not share information. Greater transparency improves response, while dependence on one route or supplier can increase vulnerability.\n\n## Efficiency versus resilience\n\nA low-cost supplier can reduce expenses under normal conditions, but complete dependence on one source raises interruption risk. Organizations may diversify suppliers, keep appropriate inventory, identify bottlenecks and test contingency plans. No single design suits every product; choices depend on value, perishability, storage costs and the likelihood of disruption.\n\n## Reading economic headlines\n\nWhen a report says a disruption will affect prices, ask which product, region, period and route are involved. A delay affecting one component does not automatically prove that all prices will rise. Inventory and substitutes may absorb part of the impact. Distinguish an observed disruption from a future possibility and from a forecast based on assumptions.\n\n## Sources and limitations\n\nThe World Bank publishes material on trade and development, while UN Trade and Development covers transport, trade and logistics. These resources explain the wider system, but estimating the effect of a specific event requires current data about the route, product, inventory and local prices.","sources":[{"title":"Trade","publisher":"World Bank","url":"https://www.worldbank.org/en/topic/trade"},{"title":"Transport and Trade Logistics","publisher":"UN Trade and Development (UNCTAD)","url":"https://unctad.org/topic/transport-and-trade-logistics"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Container_ship_in_Hamburg.jpg?width=1200","imageAlt":"A container ship in a port","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"world-climate-risks-en","section":"world","language":"en","title":"How climate risks cross borders","summary":"An introduction to cross-border climate risks, from greenhouse gas emissions to food, water, infrastructure and international cooperation.","body":"## Why climate risk is global\nThe climate system is affected by the accumulation of greenhouse gases in the atmosphere, and the effects of emissions do not stop at the border of the country where they originate. Risks differ across regions because of geography, resources, infrastructure and preparedness, but links through food, trade, migration and energy can make impacts cross borders.\n\n## Risks take different forms\n\nRisks include heatwaves, floods, drought, sea-level rise and changing rainfall patterns. They can also affect ecosystems, health and agricultural output. Not every place faces the same exposure; outcomes depend on the intensity, duration and frequency of an event and on the readiness of communities and infrastructure.\n\n## How effects travel\n\nDrought in a producing region can change harvests, prices and trade elsewhere. Ports, roads and energy systems may be affected by heat or flooding, delaying goods and services. These connections do not mean every food-price increase is caused by climate change. Production, inventory, transport, policy and other economic factors must also be examined.\n\n## Mitigation and adaptation\n\nMitigation aims to reduce greenhouse gas emissions or increase their removal, while adaptation aims to reduce harm and prepare for current and expected effects. Examples include improving energy efficiency, changing transport systems, protecting natural ecosystems, managing water and strengthening early-warning systems. Options depend on local resources and conditions.\n\n## Why reliable data matters\n\nLong-term measurements, models and comparisons across independent sources help distinguish trends from natural variability. Reports should identify the period, region and indicator, and should not present a future scenario as a certain outcome. Model limitations and assumptions matter because results can vary with emissions pathways and preparedness.\n\n## International cooperation\n\nSome responses require coordination on finance, data, technology, trade and disaster management. Countries differ in responsibilities, capacity and needs, so agreements need measurable goals and transparent monitoring. A broad public commitment is not enough without implementation plans and evidence of progress.\n\n## A responsible summary\n\nWhen reading climate news, check the scientific organization, period, region and type of risk. Distinguish current observations from projections and scenarios, and do not attribute a single event to climate change without suitable analysis. Understanding global connections helps preparedness but does not remove the need for evidence for each specific claim.\n\n## Sources and limitations\n\nThe Intergovernmental Panel on Climate Change publishes scientific assessments, while UN Climate Change provides information on international cooperation. Consult the specific report, publication date and scope rather than relying on a headline or excerpt.","sources":[{"title":"Assessment Reports","publisher":"Intergovernmental Panel on Climate Change","url":"https://www.ipcc.ch/assessment-report/ar6/"},{"title":"Climate Action","publisher":"UN Climate Change","url":"https://unfccc.int/climate-action"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Climate_Change_Schematic.svg?width=1200","imageAlt":"A schematic of the greenhouse effect","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"art-reading-film-language-ar","section":"art","language":"ar","title":"كيف نفهم لغة الصورة في السينما؟","summary":"مدخل لفهم التكوين وحركة الكاميرا والمونتاج والصوت بوصفها اختيارات فنية تؤثر في معنى المشهد.","body":"## الصورة تحكي قبل الحوار\n\nلا يعتمد فهم الفيلم على الحوار وحده. فموضع الشخص داخل الكادر، والمسافة بينه وبين الكاميرا، والإضاءة والألوان وحركة الممثلين قد تنقل معلومات عن القوة أو الخوف أو العزلة قبل أن ينطق أحد بكلمة. هذه الإشارات لا تحمل معنى ثابتًا في كل الثقافات والأفلام؛ لذلك يبدأ التحليل بوصف ما نراه، ثم يسأل كيف يخدم السياق الدرامي.\n\n## التكوين وحجم اللقطة\n\nيحدد التكوين ما يظهر وما يبقى خارج الإطار. وقد تجعل اللقطة الواسعة الشخصية صغيرة أمام المكان، بينما تبرز اللقطة القريبة تعبير الوجه وتفاصيله. لكن لا ينبغي تحويل هذه الملاحظات إلى قاموس جامد؛ فاللقطة القريبة قد تعبر عن الحميمية أو التهديد بحسب الأداء والمونتاج والموسيقى وما سبقها من أحداث.\n\n## حركة الكاميرا والزمن\n\nيمكن لحركة الكاميرا أن تتبع شخصية أو تكشف معلومة أو تصنع إحساسًا بعدم الاستقرار. أما اللقطة الثابتة فقد تمنح المشاهد وقتًا لملاحظة المكان والعلاقات داخله. ويتشكل الإيقاع أيضًا من مدة اللقطات وطريقة الانتقال بينها؛ فالمونتاج السريع قد يخلق توترًا، بينما يسمح الإيقاع الأبطأ بالتأمل، لكن الأثر يتوقف على السياق لا على السرعة وحدها.\n\n## الصوت والموسيقى\n\nيشمل الصوت الكلام والموسيقى والضوضاء والصمت. وقد يأتي صوت من خارج الصورة فيوسّع العالم الذي يتخيله المشاهد، أو تتوقف الموسيقى لتجعل تفصيلًا صغيرًا أكثر حضورًا. ومن المفيد التمييز بين ما نراه وما نسمعه، ثم ملاحظة ما إذا كان الصوت يؤكد الصورة أو يناقضها أو يضيف إليها معلومة جديدة.\n\n## من الملاحظة إلى التفسير\n\nابدأ بتحديد اختيار واضح في المشهد، مثل زاوية الكاميرا أو تغير الإضاءة، ثم اشرح أثره المحتمل واربطه بما يحدث للشخصيات. بعد ذلك اختبر تفسيرك بمشهد آخر، ولا تفترض أن كل لون أو حركة تحمل رمزًا مقصودًا. التحليل الجيد يقدم قرائن قابلة للنقاش، ويعترف بوجود قراءات بديلة بدل إعلان معنى وحيد نهائي.\n\n## حدود القراءة\n\nتساعد معرفة ظروف الإنتاج ونوع الفيلم وتاريخه على فهم الاختيارات، لكنها لا تلغي دور المشاهد أو اختلاف الخبرات الثقافية. كما أن جودة الفيلم لا تقاس بعنصر منفرد؛ فالتصوير المميز قد لا ينقذ بناءً دراميًا ضعيفًا، والمشهد البسيط قد ينجح بسبب توقيته وأدائه. الهدف هو بناء تفسير واضح من تفاصيل المشهد، لا حفظ مصطلحات منفصلة.","sources":[{"title":"Film education","publisher":"British Film Institute","url":"https://www.bfi.org.uk/film-tv-people/film-education"},{"title":"Motion picture","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/motion-picture"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Film_reel.svg?width=1200","imageAlt":"بكرة فيلم سينمائي","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"art-literature-context-ar","section":"art","language":"ar","title":"كيف يغيّر السياق فهم العمل الأدبي؟","summary":"طريقة لقراءة الرواية والقصيدة في ضوء اللغة والبناء والتاريخ من دون اختزال النص في سيرة الكاتب أو عصره.","body":"## النص هو نقطة البداية\n\nيبدأ تحليل العمل الأدبي من الكلمات والصور والإيقاع والشخصيات وطريقة ترتيب الأحداث. لا يكفي أن نعرف ما الذي يحدث في الرواية؛ ينبغي أن نسأل كيف يقدمه الكاتب، وما الذي يعرفه القارئ في كل مرحلة، ولماذا اختير هذا الصوت السردي دون غيره. هذه التفاصيل تقدم أدلة داخل النص يمكن الرجوع إليها ومناقشتها.\n\n## اللغة والشكل\n\nتؤثر الاستعارة والتكرار والجمل القصيرة والطويلة والحوار في تجربة القراءة. وقد يخلق التكرار إلحاحًا أو يربط صورًا متباعدة، بينما يتيح تعدد الأصوات عرض خلافات لا يحسمها راوٍ واحد. ولا تحمل الأداة الأدبية قيمة مستقلة عن استعمالها؛ فالتكرار قد يكون مؤثرًا في موضع ومملًا في موضع آخر إذا لم يضف معنى أو إيقاعًا.\n\n## الزمن والمكان\n\nيساعد السياق التاريخي والاجتماعي على تفسير العادات والمؤسسات والمفردات التي تظهر في النص. لكن المعرفة الخارجية لا ينبغي أن تحل محل القراءة المباشرة. قد يصور الكاتب عصره بانتقائية أو ينتقد الروايات السائدة عنه، لذلك يجب الفصل بين الوقائع التي تثبتها الوثائق وبين العالم المتخيل الذي يبنيه العمل.\n\n## الكاتب والقارئ\n\nيمكن لسيرة الكاتب أن تفتح سؤالًا مهمًا، لكنها لا تثبت وحدها معنى النص. فالشخصية الروائية ليست نسخة آلية من المؤلف، والراوي قد يكون محدود المعرفة أو غير موثوق. من الأفضل مقارنة الفرضية بأكثر من موضع داخل العمل، والانتباه إلى التناقضات والتحولات بدل انتقاء جملة واحدة تؤيد الانطباع الأول.\n\n## المقارنة دون تسطيح\n\nعند مقارنة عملين، حدد سؤالًا مشتركًا مثل الذاكرة أو العدالة أو الانتماء، ثم لاحظ اختلاف الأسلوب والبناء والظروف. لا يكفي القول إن العملين يتناولان الموضوع نفسه؛ المهم بيان كيف يمنح كل منهما الموضوع شكلًا مختلفًا. وتفيد المقارنة حين تكشف الفروق بقدر ما تكشف التشابهات، مع تجنب تعميم تجربة واحدة على أدب بلد كامل.\n\n## خلاصة عملية\n\nدوّن ملاحظة محددة، واستشهد بعبارة قصيرة من النص عند الحاجة، ثم اشرح كيف تدعم استنتاجك. افصل بين وصف ما يقوله النص وبين تفسيرك له، وابحث عن شواهد قد تعارض قراءتك. السياق يثري الفهم لكنه لا يفرض نتيجة واحدة، والقراءة الأقوى هي التي تشرح أدلتها وتعترف بما يظل مفتوحًا للتأويل.","sources":[{"title":"Literature","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/literature"},{"title":"Culture and arts","publisher":"UNESCO","url":"https://www.unesco.org/en/culture-and-arts"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Bookshelf.jpg?width=1200","imageAlt":"رفوف كتب","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"arab-regional-cooperation-ar","section":"arab","language":"ar","title":"كيف يعمل التعاون بين الدول العربية؟","summary":"شرح لدور المؤسسات الإقليمية والاتفاقات والتنسيق، مع التمييز بين الأهداف المعلنة والنتائج التي تحتاج إلى بيانات مستقلة.","body":"## ما المقصود بالتعاون الإقليمي؟\n\nيعني التعاون الإقليمي أن تتفق دول متجاورة أو متقاربة على معالجة مسائل تتجاوز حدود الدولة الواحدة، مثل التجارة والنقل والصحة والتعليم والأمن الغذائي. وقد يتم ذلك عبر اتفاقات أو لجان فنية أو اجتماعات دورية أو مشروعات مشتركة. وجود مؤسسة أو اتفاق لا يثبت وحده نجاح التعاون؛ بل يجب النظر إلى التنفيذ والتمويل والنتائج الملموسة.\n\n## دور المؤسسات المشتركة\n\nتتيح جامعة الدول العربية إطارًا للتشاور بين الدول الأعضاء وتنسيق مواقفها في قضايا مشتركة. وتختلف صلاحيات المؤسسة الإقليمية عن صلاحيات الحكومة الوطنية؛ فالتوصيات السياسية لا تتحول تلقائيًا إلى قوانين نافذة داخل كل دولة، وقد يتطلب التنفيذ قرارات وطنية وميزانيات ومؤسسات قادرة على المتابعة. لذلك ينبغي قراءة نص الاتفاق ومعرفة الجهة المسؤولة عن تطبيقه.\n\n## المصالح والاختلافات\n\nتتقاطع مصالح الدول في بعض الملفات، لكنها لا تتطابق دائمًا. تختلف الموارد والاحتياجات الاقتصادية والأولويات السياسية والقدرات الإدارية من بلد إلى آخر، وقد يؤثر ذلك في سرعة تنفيذ أي مبادرة. يفسر هذا بعض التباين في النتائج، لكنه لا يبرر افتراض الفشل أو النجاح مسبقًا؛ فكل مبادرة تحتاج إلى تقييم خاص بأهدافها ومواردها.\n\n## كيف نقيس النتائج؟\n\nمن المفيد تحويل الهدف العام إلى مؤشرات يمكن فحصها: هل انخفض وقت عبور البضائع؟ هل زادت فرص الوصول إلى خدمة؟ هل نُفذت الميزانية المعلنة؟ هل نُشرت بيانات قابلة للمقارنة؟ وينبغي تحديد خط أساس وفترة زمنية ومصدر البيانات، لأن عدد الاجتماعات أو البيانات الصحفية يقيس النشاط المؤسسي ولا يقيس بالضرورة أثره على حياة الناس.\n\n## مصادر المعلومات\n\nتوضح الوثائق الرسمية أهداف المؤسسات والاتفاقات، لكنها قد تركز على ما تعلنه الجهة عن نفسها. لذلك تقارن القراءة المتوازنة بين النصوص الرسمية والبيانات الإحصائية وتقارير المتابعة والأبحاث المستقلة. وإذا اختلفت الأرقام، فيجب التحقق من تعريف المؤشر وتاريخ القياس ونطاق الدول المشمولة قبل إعلان وجود تناقض.\n\n## ما الذي يحد التعاون؟\n\nتؤثر الخلافات السياسية وتفاوت القدرات والتمويل وتغير الأولويات في استمرار المبادرات. كما أن نجاح مشروع في مجال واحد لا يضمن نجاح مشروع آخر، لأن طبيعة المشكلة والمؤسسات المشاركة تختلف. يساعد الاعتراف بهذه القيود على تقديم تقييم أكثر دقة من الاكتفاء بوصف التعاون بأنه ناجح أو فاشل بصورة مطلقة.\n\n## خلاصة\n\nافهم الهدف الرسمي، ثم تتبع آلية التنفيذ والميزانية والنتائج المنشورة، وقارنها بمصدر مستقل. وميّز بين إعلان النية وإقرار الاتفاق وتنفيذه وقياس أثره. هذه المراحل ليست شيئًا واحدًا، وفصلها يمنح القارئ صورة أوضح عن إمكانات التعاون الإقليمي وحدوده وما يحتاج إلى تحقق إضافي.","sources":[{"title":"About the League","publisher":"League of Arab States","url":"https://www.lasportal.org/en/Pages/default.aspx"},{"title":"Arab region","publisher":"United Nations Economic and Social Commission for Western Asia","url":"https://www.unescwa.org/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Flag_of_the_Arab_League.svg?width=1200","imageAlt":"علم جامعة الدول العربية","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"arab-water-cooperation-ar","section":"arab","language":"ar","title":"لماذا تحتاج قضايا المياه إلى تعاون إقليمي؟","summary":"مدخل لفهم الأحواض المائية المشتركة وإدارة الطلب والبيانات والتفاوض، مع توضيح أن الحلول تختلف بحسب القانون والجغرافيا واحتياجات السكان.","body":"## المياه لا تتوقف عند الحدود\n\nتتصل الأنهار والمياه الجوفية والأنظمة البيئية بحدود سياسية لا تطابق دائمًا حدود الطبيعة. وقد تعتمد مجتمعات متعددة على المورد نفسه للشرب والزراعة والصناعة والنظم البيئية. لذلك قد يؤثر قرار محلي في كمية المياه أو توقيت وصولها أو جودتها في مناطق أخرى، ويصبح تبادل البيانات والتنسيق جزءًا من إدارة المخاطر.\n\n## البيانات قبل الاستنتاج\n\nتحتاج المقارنة إلى بيانات عن الأمطار والتدفق والسحب والتخزين وجودة المياه والطلب المتوقع. لكن الأرقام لا تكون قابلة للمقارنة إذا اختلفت طريقة القياس أو الفترة الزمنية أو تعريف المؤشر. من المهم نشر منهجية جمع البيانات وحدودها، والتمييز بين القياس المباشر والتقدير والنموذج، لأن عدم اليقين لا يعني أن كل الأرقام متساوية في القوة.\n\n## إدارة الطلب والكفاءة\n\nيمكن تقليل الضغط على الموارد عبر إصلاح التسربات وتحسين كفاءة الري وإعادة استخدام المياه المعالجة حيث تسمح المعايير الصحية والبيئية. ولا يوجد حل واحد مناسب لكل مكان؛ فالتكلفة والطاقة المتاحة ونوعية المياه والبنية الأساسية والقدرة على الصيانة تؤثر في الاختيار. كما أن زيادة الكفاءة لا تضمن انخفاض الاستهلاك الكلي إذا توسع الاستخدام في الوقت نفسه.\n\n## التعاون وتبادل المعلومات\n\nتساعد اللجان المشتركة والاتفاقات على تحديد إجراءات الإخطار وتبادل البيانات وتسوية الخلافات، لكنها تحتاج إلى تمويل مستمر ومشاركة فنية وشفافية في التنفيذ. وقد تكون البيانات المشتركة مفيدة حتى عندما يستمر الخلاف السياسي، لأنها تتيح للأطراف مناقشة الأرقام والافتراضات بدل الاعتماد على تقديرات متعارضة لا يمكن اختبارها.\n\n## الإنصاف والاحتياجات\n\nينبغي أن تراعي الإدارة احتياجات السكان وسبل العيش والبيئة، لا حجم المورد وحده. وتختلف الأولويات بين المدن والمناطق الزراعية والمجتمعات التي تعتمد على المياه الجوفية. لذلك يتطلب التقييم تحديد من يستفيد ومن يتحمل التكلفة، وهل توجد آليات للشكاوى والتعويض أو لحماية الفئات الأكثر تعرضًا لنقص الخدمة.\n\n## تقييم السياسات\n\nلا يكفي الإعلان عن مشروع أو توقيع مذكرة تفاهم لإثبات تحسن الأمن المائي. ينبغي تتبع التنفيذ ومؤشرات الخدمة وجودة المياه والتكلفة والآثار البيئية عبر الزمن، مع مقارنة النتائج بخط أساس واضح. وإذا لم تتوفر بيانات مستقلة، يجب وصف النتيجة بأنها غير محسومة بدل تحويل الهدف المعلن إلى نجاح مؤكد.\n\n## خلاصة\n\nتجمع إدارة المياه بين العلم والبنية الأساسية والقانون والسياسة العامة. ويساعد التعاون على تحسين المعلومات وتنسيق الاستجابة، لكنه لا يلغي اختلاف المصالح ولا يعوض نقص التنفيذ. القراءة الدقيقة تحدد الحوض والجهات المعنية والبيانات والفترة الزمنية، ثم تشرح ما تثبته الأدلة وما لا تزال بحاجة إلى قياس أو اتفاق.","sources":[{"title":"Water","publisher":"United Nations Economic and Social Commission for Western Asia","url":"https://www.unescwa.org/water"},{"title":"Water and sustainable development","publisher":"United Nations","url":"https://www.un.org/sustainabledevelopment/water-and-sanitation/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Flag_of_the_Arab_League.svg?width=1200","imageAlt":"علم جامعة الدول العربية","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"art-reading-film-language-en","section":"art","language":"en","title":"How to read the visual language of film","summary":"A practical guide to framing, camera movement, editing and sound as artistic choices that shape a scene without imposing one fixed interpretation.","body":"## Images communicate before dialogue\n\nA film does not rely on dialogue alone. The position of a person within the frame, the distance from the camera, lighting, color and movement can suggest power, fear or isolation before anyone speaks. These signals do not have one fixed meaning across all films and cultures. Begin by describing what is visible, then ask how the choice relates to the scene and its dramatic context.\n\n## Framing and shot size\n\nFraming determines what the audience can see and what remains outside the image. A wide shot may make a character appear small in a location, while a close-up draws attention to facial expression and detail. Neither choice has a universal meaning: a close-up can create intimacy or threat depending on performance, editing, music and what happened before the shot.\n\n## Camera movement and time\n\nA moving camera can follow a character, reveal information or create instability. A fixed shot may give viewers time to notice a space and the relationships within it. Rhythm also depends on shot duration and transitions. Rapid editing can intensify tension, while a slower pace may support reflection, but the effect depends on context rather than speed alone.\n\n## Sound and music\n\nSound includes dialogue, music, environmental noise and silence. A sound from outside the frame can make the imagined world larger, while a pause in music may make a small detail more noticeable. Separate what is seen from what is heard, then ask whether the sound confirms the image, contradicts it or adds information the image cannot provide.\n\n## From observation to interpretation\n\nChoose a specific feature of a scene, such as camera angle or a change in lighting, describe its possible effect and connect it to what the characters are doing. Test the interpretation against another scene rather than assuming that every color or movement is a deliberate symbol. Strong analysis offers reasons that other viewers can discuss and acknowledges plausible alternative readings.\n\n## Limits of interpretation\n\nKnowledge of production, genre and film history can clarify choices, but it does not remove the role of viewers or cultural differences. Film quality cannot be measured by one element alone: striking cinematography may not compensate for a weak dramatic structure, while a simple scene may succeed through timing and performance. The goal is to build a clear interpretation from details, not to memorize isolated terms.","sources":[{"title":"Film education","publisher":"British Film Institute","url":"https://www.bfi.org.uk/film-tv-people/film-education"},{"title":"Motion picture","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/motion-picture"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Film_reel.svg?width=1200","imageAlt":"A film reel","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"art-literature-context-en","section":"art","language":"en","title":"How context changes the way we read literature","summary":"A method for reading fiction and poetry through language, structure, history and authorial context without reducing a text to the writer biography or period.","body":"## The text comes first\n\nAnalysis begins with the words, images, rhythm, characters and arrangement of events. It is not enough to know what happens in a novel; ask how the writer presents it, what the reader knows at each stage and why one narrative voice was chosen over another. These features provide evidence within the text that can be revisited and discussed.\n\n## Language and form\n\nMetaphor, repetition, sentence length and dialogue shape the reading experience. Repetition may create urgency or connect distant images, while multiple voices can present disagreements without a single narrator resolving them. A literary device has no value independent of its use: repetition may be powerful in one passage and tedious in another if it adds no meaning or rhythm.\n\n## Time and place\n\nHistorical and social context can explain customs, institutions and vocabulary in a text. External knowledge should not replace direct reading, however. A writer may portray an era selectively or challenge its dominant accounts, so readers should distinguish facts supported by historical documents from the imagined world built by the work.\n\n## Writer and reader\n\nA writer biography may raise useful questions, but it cannot prove a text meaning by itself. A fictional character is not automatically a copy of the author, and a narrator may have limited knowledge or be unreliable. Test a hypothesis against more than one passage and attend to contradictions and changes rather than selecting one sentence that confirms an initial impression.\n\n## Comparison without flattening\n\nWhen comparing two works, choose a shared question such as memory, justice or belonging, then examine differences in style, structure and circumstance. It is not enough to say both works discuss the same topic; explain how each gives the topic a different form. Comparison is useful when it reveals differences as well as similarities and avoids treating one work as representative of an entire national literature.\n\n## A practical method\n\nWrite down a specific observation, quote a short phrase when necessary and explain how it supports an interpretation. Separate what the text says from what you infer, and look for evidence that could challenge your reading. Context enriches understanding but does not force one final answer. The strongest interpretation explains its evidence and admits what remains open to debate.","sources":[{"title":"Literature","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/literature"},{"title":"Culture and arts","publisher":"UNESCO","url":"https://www.unesco.org/en/culture-and-arts"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Bookshelf.jpg?width=1200","imageAlt":"Bookshelves","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"arab-regional-cooperation-en","section":"arab","language":"en","title":"How cooperation among Arab states works","summary":"An explanation of regional institutions, agreements and coordination, distinguishing stated goals from outcomes that require independent data.","body":"## What regional cooperation means\n\nRegional cooperation occurs when neighboring or closely connected states coordinate on issues that cross borders, including trade, transport, health, education and food security. It may take the form of agreements, technical committees, regular meetings or joint projects. The existence of an institution or agreement does not prove that cooperation has succeeded; implementation, funding and measurable outcomes still matter.\n\n## The role of shared institutions\n\nThe League of Arab States provides a framework for consultation among member states and coordination on common issues. A regional institution has different powers from a national government: a political recommendation does not automatically become enforceable law in every country. Implementation may require national decisions, budgets and agencies able to monitor progress. Readers should therefore check the agreement and identify who is responsible for carrying it out.\n\n## Interests and differences\n\nStates share some interests but do not always have identical priorities. Resources, economic needs, political goals and administrative capacity vary across countries, affecting how quickly a joint initiative can proceed. These differences can help explain uneven results, but they do not prove success or failure in advance. Each initiative needs an assessment based on its own objectives, resources and evidence.\n\n## Measuring outcomes\n\nA broad goal should be translated into indicators that can be checked. Did border transit time fall? Did access to a service improve? Was the announced budget implemented? Were comparable data published? The number of meetings or press statements measures institutional activity, not necessarily the effect on people lives. A useful evaluation specifies a baseline, a time period and a source for each indicator.\n\n## Sources and transparency\n\nOfficial documents explain institutional goals and agreements, but they may emphasize the organization own account of its work. A balanced review compares official texts with statistics, monitoring reports and independent research. If figures differ, check the indicator definition, measurement date and countries included before declaring a contradiction. Different measures may describe different parts of the same problem.\n\n## What limits cooperation\n\nPolitical disputes, unequal capacity, funding constraints and shifting priorities can interrupt joint initiatives. Success in one policy area does not guarantee success in another because the problem and institutions involved may be different. Recognizing these limits produces a more accurate assessment than labeling regional cooperation as either wholly successful or wholly ineffective.\n\n## Conclusion\n\nStart with the stated goal, then trace the implementation mechanism, budget and published outcomes, and compare them with an independent source. Distinguish an announcement, an adopted agreement, actual implementation and measured impact. These are separate stages. Keeping them separate gives readers a clearer view of the opportunities, limits and unresolved questions surrounding regional cooperation.","sources":[{"title":"About the League","publisher":"League of Arab States","url":"https://www.lasportal.org/en/Pages/default.aspx"},{"title":"Arab region","publisher":"United Nations Economic and Social Commission for Western Asia","url":"https://www.unescwa.org/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Flag_of_the_Arab_League.svg?width=1200","imageAlt":"Flag of the League of Arab States","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"arab-water-cooperation-en","section":"arab","language":"en","title":"Why water management needs regional cooperation","summary":"An introduction to shared watersheds, demand management, data and negotiation, showing why solutions depend on law, geography and local needs.","body":"## Water crosses borders\n\nRivers, groundwater and ecosystems do not always follow political boundaries. Several communities may depend on the same resource for drinking water, agriculture, industry and the environment. A local decision can affect water quantity, timing or quality elsewhere, making data exchange and coordinated risk management important parts of water policy.\n\n## Data before conclusions\n\nA useful comparison needs information about rainfall, river flow, withdrawals, storage, water quality and expected demand. Figures are not comparable when measurement methods, time periods or indicator definitions differ. Reports should explain how data were collected and distinguish direct measurements from estimates and models. Uncertainty does not mean all numbers have equal evidential value.\n\n## Managing demand and efficiency\n\nPressure on water resources can be reduced through leak repair, more efficient irrigation and reuse of treated water where health and environmental standards permit it. No single solution fits every location: cost, energy supply, water quality, infrastructure and maintenance capacity all influence the choice. Efficiency also does not guarantee lower total consumption if use expands at the same time.\n\n## Cooperation and information sharing\n\nJoint committees and agreements can set procedures for notification, data exchange and dispute resolution, but they need sustained funding, technical participation and transparent implementation. Shared information can remain useful even when political disagreements continue because it allows parties to discuss numbers and assumptions rather than relying on incompatible estimates that cannot be tested.\n\n## Fairness and local needs\n\nWater management should consider people, livelihoods and ecosystems, not only the size of a resource. Priorities differ between cities, farming areas and communities that depend on groundwater. Evaluation should identify who benefits, who bears the cost and whether there are mechanisms for complaints, compensation or protecting groups most exposed to service shortages.\n\n## Evaluating policy\n\nAn announced project or signed memorandum does not prove that water security improved. Track implementation, service indicators, water quality, costs and environmental effects over time against a clear baseline. If independent data are unavailable, describe the outcome as unresolved rather than treating an official target as a confirmed success.\n\n## Conclusion\n\nWater management combines science, infrastructure, law and public policy. Cooperation can improve information and coordinate responses, but it does not remove conflicting interests or replace implementation. A careful review identifies the watershed, relevant institutions, data and time period, then explains what the evidence establishes and what still requires measurement or agreement.","sources":[{"title":"Water","publisher":"United Nations Economic and Social Commission for Western Asia","url":"https://www.unescwa.org/water"},{"title":"Water and sustainable development","publisher":"United Nations","url":"https://www.un.org/sustainabledevelopment/water-and-sanitation/"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Flag_of_the_Arab_League.svg?width=1200","imageAlt":"Flag of the League of Arab States","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"science-read-space-observations-en","section":"science","language":"en","title":"How to read evidence from space discoveries","summary":"A guide to telescope images, astronomical data, uncertainty and independent confirmation.","body":"## Observation and interpretation\n\nAstronomy begins with measurements of light, radiation or motion, which are then transformed into images, tables and models. A published telescope image may be processed to reveal features that human eyes cannot see directly, so readers should check the mission notes and learn which wavelengths and display colors were used. Processing does not automatically make an image misleading; it explains how researchers moved from recorded signals to a visual representation and which conclusions the representation can support.\n\n## What a telescope can tell us\n\nDifferent telescopes observe different kinds of light and cover different regions of the sky at different levels of detail. The James Webb Space Telescope observes infrared light, helping researchers investigate distant or cool objects and regions partly obscured by dust. Every instrument still has limits related to sensitivity, exposure time, noise and calibration. A striking image does not mean that every property or the full history of an object is now known.\n\n## From measurements to a claim\n\nResearchers compare observations with models and alternative explanations, then test whether the data support one interpretation or several. Conclusions can change when additional observations become available or when a better analysis method is developed. Readers should separate what was measured directly, what the research team inferred and what remains a hypothesis requiring further tests. This distinction matters when headlines describe every new result as a final discovery.\n\n## Why independent confirmation matters\n\nConfidence grows when independent measurements or different instruments support a similar interpretation, or when another team can analyze the data and reach a comparable result. Independence does not require every team to use the same instrument; observations from other observatories can provide an additional check. Many websites may repeat a single press release, so a large number of headlines does not necessarily mean many independent confirmations.\n\n## How to read a space-science story\n\nLook for the mission or instrument name, the observation date and the scientific organization responsible for the data. Read the original study or mission explanation when available, and distinguish measurements from interpretation. Check what the researchers say they still do not know. If a story relies only on a conference announcement, treat it as an early description until the underlying details can be reviewed.\n\n## What remains uncertain\n\nMeasurements may be real while their interpretation remains unsettled. Estimates of distance, mass or age can change as instruments improve and additional observations arrive. That does not undermine science; it illustrates how knowledge is revised. A careful account explains why a finding matters without turning a possibility into certainty or hiding the questions that remain open.","sources":[{"title":"Webb Space Telescope","publisher":"NASA","url":"https://science.nasa.gov/mission/webb/"},{"title":"Webb Space Science","publisher":"European Space Agency","url":"https://www.esa.int/Science_Exploration/Space_Science/Webb"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/James_Webb_Space_Telescope_Mirror.jpg?width=1200","imageAlt":"James Webb Space Telescope mirror","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"science-test-scientific-claims-en","section":"science","language":"en","title":"How to test scientific claims","summary":"A method for checking research questions, study design, uncertainty and independent replication.","body":"## Start with a precise question\n\nA useful scientific claim can be stated clearly enough to be examined, such as a question about the relationship between two variables or the effect of a defined intervention. Broad statements that a substance cures every disease or that a technology changes everything do not specify a measurable outcome. A precise question helps researchers choose suitable evidence instead of collecting information that merely supports an initial impression.\n\n## Check how data were collected\n\nEvidence strength depends on study design, sample size, participant selection and measurement methods. An observational study can reveal an association, but it cannot by itself prove that one factor caused another. Controlled experiments can help test causation when they are suitable and ethical, yet results remain tied to the conditions of the experiment and to how well the sample represents a wider population.\n\n## Association is not causation\n\nWhen two events occur together, they may share a common cause or depend on a factor that was not measured. For example, people who use a health service may have better outcomes partly because they differ in age, income or the severity of their condition. Researchers therefore consider confounding factors, use appropriate statistical methods and compare findings with other evidence before making a causal claim.\n\n## What peer review can do\n\nReview by specialists allows methods, analysis and clarity to be examined before publication in many journals. It is not an absolute guarantee of correctness: errors can remain, knowledge can change, and papers can later be corrected or withdrawn. Peer review is one layer of scrutiny alongside transparent data, reproducible analysis, repeated findings and evaluation of the full body of evidence.\n\n## Read the results and limitations\n\nLook beyond a single statistical value. Check the number of participants, time period, outcome measure and size of the observed effect. Read the limitations section to understand what the study cannot establish. If a result is preliminary or appears in a non-peer-reviewed preprint, say so when sharing it rather than presenting it as settled scientific consensus.\n\n## Compare independent sources\n\nSystematic reviews and reports from independent scientific organizations can help establish whether a result fits the wider evidence. Confirm that sources address the same question and do not simply repeat one press release. When findings conflict, examine differences in methods, populations and variable definitions instead of automatically choosing the most dramatic conclusion.\n\n## A practical checklist\n\nAsk what was actually measured, how it was measured, what alternative explanations remain and whether the result has been replicated. Separate the study data from the authors interpretation and from media headlines. You do not need to become an expert in every field to recognize overstatement; these questions help you assess confidence fairly and acknowledge what the evidence has not yet settled.","sources":[{"title":"Understanding Science","publisher":"University of California Museum of Paleontology","url":"https://undsci.berkeley.edu/"},{"title":"Science and Engineering Indicators","publisher":"National Science Foundation","url":"https://ncses.nsf.gov/indicators"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Microscope.jpg?width=1200","imageAlt":"Microscope used in scientific research","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"technology-understand-generative-ai-ar","section":"technology","language":"ar","title":"الذكاء الاصطناعي التوليدي: كيف يعمل وما حدوده؟","summary":"شرح للنماذج التوليدية وأخطائها المحتملة والتحيز والخصوصية وطرق التحقق من المخرجات.","body":"## ما الذي يولده النموذج؟\n\nيتعلم الذكاء الاصطناعي التوليدي أنماطًا من بيانات التدريب ثم يستخدمها لإنتاج نص أو صورة أو صوت أو شيفرة استجابةً لطلب المستخدم. لا يعني ذلك أنه يملك قاعدة حقائق كاملة أو أنه يفهم كل عبارة بالطريقة البشرية. تعتمد النتيجة على البيانات والتصميم والسياق والتعليمات، وقد تبدو الإجابة واثقة ومنظمة حتى عندما تكون بعض تفاصيلها غير صحيحة.\n\n## لماذا تظهر أخطاء مقنعة؟\n\nقد يكمل النموذج نمطًا لغويًا مألوفًا بدل أن يتحقق من حقيقة خارجية، وقد يخلط بين أسماء متشابهة أو يركب تفاصيل من مصادر مختلفة. لذلك لا يكفي الأسلوب الجيد أو طول الإجابة لإثبات الدقة. عندما تتعلق الإجابة بشخص أو رقم أو تاريخ أو قرار حالي، يجب الرجوع إلى مصدر مباشر مناسب وفحص ما إذا كان المصدر يدعم الادعاء المحدد لا الموضوع العام فقط.\n\n## البيانات والتحيز\n\nتعكس مخرجات الأنظمة بعض خصائص البيانات التي تعلمت منها، بما فيها النقص والتحيزات التاريخية واختلاف تمثيل اللغات والفئات. قد تكون النتائج أقل دقة في سياقات أو لهجات لا تظهر بما يكفي في بيانات التدريب. ينبغي تقييم النظام على أمثلة متنوعة، وتوثيق الحالات التي يفشل فيها، وإتاحة مراجعة بشرية في القرارات التي قد تؤثر في الحقوق أو فرص العمل أو الخدمات.\n\n## الخصوصية والاستخدام المسؤول\n\nلا تضع كلمات المرور أو بيانات الهوية أو الملفات السرية في أداة لا تعرف طريقة معالجتها للمعلومات. اقرأ سياسة الخدمة، وافهم خيارات الاحتفاظ بالبيانات واستخدامها، وقلل المعلومات التي تشاركها إلى الحد الضروري. وفي المؤسسات، ينبغي تحديد من يستطيع الوصول إلى المخرجات وكيفية مراجعتها قبل نقلها إلى سجلات أو أنظمة تشغيلية.\n\n## كيف تتحقق من الإجابة؟\n\nاطلب من النظام فصل الحقائق عن الاستنتاجات والافتراضات، ثم تحقق من أهم الادعاءات في مصادر أولية أو مستقلة. افتح الرابط نفسه بدل الاكتفاء بعنوان المصدر، وتأكد من أن النص يدعم العبارة. إذا تعارض مصدران، فلا تختَر الأكثر ثقة في الصياغة؛ افحص التاريخ والسياق والجهة التي أصدرت المعلومة. واطلب تصحيحًا محددًا عند اكتشاف خطأ بدل إعادة استخدام الإجابة كما هي.\n\n## أين يفيد الإنسان؟\n\nيمكن للنظام أن يساعد في تلخيص نص طويل أو اقتراح أفكار أو شرح مفهوم أو إعداد مسودة أولية. لكنه لا يعفي المستخدم من مراجعة المعلومات، ولا ينبغي أن ينفذ وحده قرارًا عالي المخاطر. أفضل استخدام يجمع سرعة التوليد مع أدلة قابلة للفحص ومراجعة مناسبة وتوثيق للحدود.\n\n## خلاصة\n\nتعامل مع المخرجات بوصفها اقتراحًا يحتاج إلى تقييم، لا شهادة صحة تلقائية. حدد ما تريد معرفته، وافحص المصادر، واحمِ البيانات الخاصة، وراقب التحيز والأخطاء المتكررة. عندما لا تتوفر أدلة كافية، يجب أن يصرح النظام بذلك بدل اختراع تفاصيل لإكمال الإجابة.","sources":[{"title":"AI Risk Management Framework","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/itl/ai-risk-management-framework"},{"title":"Recommendation on the Ethics of Artificial Intelligence","publisher":"UNESCO","url":"https://www.unesco.org/en/artificial-intelligence/recommendation-ethics"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Computer_keyboard.jpg?width=1200","imageAlt":"لوحة مفاتيح حاسوب","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"technology-protect-online-accounts-ar","section":"technology","language":"ar","title":"تقنية الأمن السيبراني: حماية الحسابات من الاختراق","summary":"خطوات لحماية الحسابات وكشف التصيد وتحديث الأجهزة واستعادة الوصول بأمان.","body":"## ابدأ بكلمة مرور فريدة\n\nاستخدام كلمة المرور نفسها في خدمات متعددة يجعل اختراق حساب واحد خطرًا على بقية الحسابات. استخدم كلمة مرور طويلة وفريدة لكل خدمة، ويمكن لمدير كلمات المرور الموثوق أن يساعدك في إنشائها وحفظها. لا ترسل كلمات المرور عبر الرسائل ولا تكتبها في ملفات مشتركة. وإذا أبلغت الخدمة عن تسريب، غيّر كلمة المرور من الموقع أو التطبيق الرسمي لا من رابط وصل برسالة مفاجئة.\n\n## فعّل المصادقة متعددة العوامل\n\nتضيف المصادقة متعددة العوامل خطوة أخرى بعد كلمة المرور، مثل تطبيق مصادقة أو مفتاح أمان أو وسيلة تحقق أخرى. هذا لا يجعل الحساب محصنًا تمامًا، لكنه يقلل خطر الدخول بكلمة مرور مسروقة وحدها. احفظ رموز الاسترداد في مكان آمن، وحدد طريقة لاستعادة الحساب إذا فقدت الهاتف، ولا توافق على طلب تسجيل دخول لم تبدأه بنفسك.\n\n## تعرّف على رسائل التصيد\n\nقد تنتحل الرسالة صفة بنك أو شركة شحن أو جهة حكومية وتضغط عليك لاتخاذ إجراء عاجل. افحص عنوان المرسل والرابط ووجود أخطاء أو طلبات غير معتادة، ولا تعتمد على الشعار أو اسم العرض فقط. إذا طلبت الرسالة كلمة المرور أو رمز التحقق أو الدفع عبر طريقة غريبة، افتح التطبيق الرسمي يدويًا أو اتصل بالجهة عبر وسيلة تعرفها مسبقًا.\n\n## حدّث الأجهزة والتطبيقات\n\nتصلح التحديثات الأمنية ثغرات يمكن أن يستغلها المهاجمون. فعّل التحديث التلقائي عندما يكون مناسبًا، وأزل التطبيقات التي لم تعد تستخدمها، واقفل الهاتف والحاسوب برمز قوي. استخدم نسخًا احتياطية منتظمة للملفات المهمة، واختبر إمكانية استعادتها؛ فوجود نسخة لم تختبرها لا يضمن أنك ستستطيع استرجاع بياناتك وقت الحاجة.\n\n## ماذا تفعل عند الاشتباه بالاختراق؟\n\nاستخدم جهازًا موثوقًا لتغيير كلمة المرور، وأنهِ الجلسات غير المعروفة، وراجع وسائل الاسترداد وقواعد إعادة توجيه البريد. اتصل بمزود الخدمة أو البنك من قناة رسمية إذا كانت معلومات مالية معرضة للخطر. احتفظ بالرسائل والسجلات المهمة، ولا تدفع لشخص مجهول يعدك باستعادة الحساب قبل التحقق من هويته وخبرته.\n\n## لا تشارك رموز التحقق\n\nرمز التحقق المؤقت يعادل مفتاحًا قصير العمر للحساب، وقد يطلبه المحتال بحجة أنه موظف دعم أو شخص يساعدك. لا تشاركه مع أي شخص، حتى لو كان يعرف اسمك أو بعض تفاصيلك. الموظف الشرعي لا يحتاج عادةً إلى أن تملي عليه رمز تسجيل الدخول الكامل كي يحمي الحساب.\n\n## خطة حماية بسيطة\n\nابدأ بالبريد الإلكتروني لأنه غالبًا وسيلة استعادة حسابات أخرى، ثم أمّن الحسابات المالية والاجتماعية. استخدم كلمات مرور فريدة ومصادقة متعددة العوامل وتحديثات منتظمة، وراجع التنبيهات والجلسات. هذه الخطوات لا تلغي كل المخاطر، لكنها تقلل فرص الاختراق وتساعدك على اكتشاف المشكلة مبكرًا.","sources":[{"title":"Secure Our World","publisher":"Cybersecurity and Infrastructure Security Agency","url":"https://www.cisa.gov/secure-our-world"},{"title":"Recognizing and Avoiding Phishing Scams","publisher":"Federal Trade Commission","url":"https://consumer.ftc.gov/articles/how-recognize-and-avoid-phishing-scams"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Computer_keyboard.jpg?width=1200","imageAlt":"لوحة مفاتيح حاسوب","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"technology-understand-generative-ai-en","section":"technology","language":"en","title":"Artificial intelligence: how generative AI works and where it fails","summary":"An accessible guide to artificial intelligence, generative models, convincing errors, bias, privacy and evidence-based verification.","body":"## What a model generates\n\nGenerative artificial intelligence learns patterns from training data and uses them to produce text, images, audio or code in response to a prompt. This does not mean that it contains a complete database of facts or understands every statement in the human sense. Output depends on data, design, context and instructions. A response can sound confident and well organized even when some details are wrong.\n\n## Why convincing errors happen\n\nA model may continue a familiar language pattern instead of checking an external fact. It can confuse people with similar names or combine details from different sources. Good writing and a long answer do not prove accuracy. For claims about a person, number, date or current decision, consult a suitable direct source and check whether it supports the specific claim rather than the general topic.\n\n## Data and bias\n\nSystem outputs can reflect gaps and historical biases in the data used to build them, including uneven representation of languages, dialects and communities. Performance may be weaker in contexts that appear rarely in training or evaluation. Responsible deployment requires testing diverse examples, documenting failures and keeping human review for decisions that may affect rights, employment, access to services or other important interests.\n\n## Privacy and responsible use\n\nDo not submit passwords, identity documents or confidential files to a service unless you understand how the information is handled. Read the service policy, understand retention and data-use options, and share only what is necessary. Organizations should define who can access outputs and how they are reviewed before the information is copied into records or operational systems.\n\n## How to verify an answer\n\nAsk the system to separate facts from inferences and assumptions, then check important claims against primary or independent sources. Open the source itself rather than relying on its title, and confirm that the page supports the statement. If sources disagree, do not choose the one that sounds most certain; compare dates, context and the organizations responsible. When an error appears, request a specific correction instead of reusing the answer unchanged.\n\n## Where human judgment matters\n\nA model can help summarize a long text, brainstorm ideas, explain a concept or prepare a first draft. It does not remove the need to review information and should not independently make high-impact decisions. Strong use combines fast generation with inspectable evidence, suitable human review and clear documentation of limitations.\n\n## Practical takeaway\n\nTreat generated output as a proposal to evaluate, not an automatic certificate of truth. Define the question, inspect sources, protect private data and watch for recurring errors or bias. When evidence is missing, a responsible system should say so instead of inventing details to complete a polished response.","sources":[{"title":"AI Risk Management Framework","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/itl/ai-risk-management-framework"},{"title":"Recommendation on the Ethics of Artificial Intelligence","publisher":"UNESCO","url":"https://www.unesco.org/en/artificial-intelligence/recommendation-ethics"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Computer_keyboard.jpg?width=1200","imageAlt":"Computer keyboard","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"technology-protect-online-accounts-en","section":"technology","language":"en","title":"Cybersecurity: how to protect online accounts","summary":"Practical steps for unique passwords, multi-factor authentication, phishing detection, software updates and recovery.","body":"## Start with unique passwords\n\nReusing one password across services turns a breach at one site into a risk for other accounts. Use a long, unique password for each service; a reputable password manager can help create and store them. Never send passwords through messages or leave them in shared files. If a service reports a breach, change the password from its official site or app rather than following a surprise link in a message.\n\n## Turn on multi-factor authentication\n\nMulti-factor authentication adds a step after the password, such as an authenticator app, security key or another verification method. It does not make an account invulnerable, but it reduces the risk of access with a stolen password alone. Store recovery codes securely, plan how to regain access if your phone is lost, and never approve a sign-in request you did not initiate.\n\n## Recognize phishing attempts\n\nA message may impersonate a bank, delivery company or government office and pressure you to act urgently. Check the sender address, link destination, unusual wording and unexpected requests. Do not rely on a logo or display name. If a message asks for a password, verification code or payment through an unusual method, open the official app manually or contact the organization through a channel you already trust.\n\n## Update devices and applications\n\nSecurity updates repair weaknesses that attackers may exploit. Enable automatic updates when appropriate, remove apps you no longer use and lock your devices with a strong passcode. Keep regular backups of important files and test that you can restore them. A backup that has never been tested does not guarantee that your information will be recoverable when you need it.\n\n## Responding to a suspected compromise\n\nUse a trusted device to change the password, end unfamiliar sessions and review recovery methods and email forwarding rules. Contact the service provider or bank through an official channel if financial information may be at risk. Preserve relevant messages and logs. Be cautious of strangers who promise to recover an account for a fee before you can verify their identity and expertise.\n\n## Never share verification codes\n\nA temporary verification code is a short-lived key to an account. A scammer may ask for it while pretending to be support staff or someone helping you. Do not share it with anyone, even if the person knows your name or some personal details. Legitimate staff generally do not need you to read out a full sign-in code to protect an account.\n\n## A simple protection plan\n\nSecure your email account first because it often helps recover other accounts, then protect financial and social accounts. Use unique passwords, multi-factor authentication and regular updates, and review alerts and active sessions. These steps do not eliminate every risk, but they lower the chance of compromise and help you detect problems earlier.","sources":[{"title":"Secure Our World","publisher":"Cybersecurity and Infrastructure Security Agency","url":"https://www.cisa.gov/secure-our-world"},{"title":"Recognizing and Avoiding Phishing Scams","publisher":"Federal Trade Commission","url":"https://consumer.ftc.gov/articles/how-recognize-and-avoid-phishing-scams"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Computer_keyboard.jpg?width=1200","imageAlt":"Computer keyboard","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"science-read-space-observations-ar","section":"science","language":"ar","title":"كيف نقرأ أدلة اكتشافات الفضاء؟","summary":"منهج لفهم صور التلسكوبات والبيانات الفلكية والتمييز بين الرصد والتفسير والادعاء المبكر.","body":"## الرصد ليس هو التفسير\n\nتبدأ المعرفة الفلكية بقياس الضوء أو الإشعاع أو الحركة، ثم تحويل البيانات إلى صورة أو جدول أو نموذج. الصورة المنشورة قد تكون معالجة لإظهار تفاصيل لا تراها العين مباشرة، لذلك ينبغي قراءة شرح فريق الرصد ومعرفة الأطوال الموجية والألوان الاصطناعية المستخدمة. لا يجعل ذلك الصورة مضللة؛ بل يوضح كيف انتقل العلماء من الإشارة الخام إلى التمثيل المرئي، وما المعلومات التي يمكن استخلاصها منه.\n\n## ما الذي يقدمه التلسكوب؟\n\nتختلف التلسكوبات في قدرتها على رصد أنواع الضوء ومجالات السماء ودرجات الدقة. يستطيع تلسكوب جيمس ويب رصد الأشعة تحت الحمراء، وهو ما يساعد الباحثين على دراسة أجسام بعيدة أو باردة أو محجوبة جزئيًا بالغبار. لكن كل جهاز له حدود مرتبطة بحساسيته ووقت الرصد والضوضاء وطريقة المعايرة. لذلك لا تعني صورة جميلة بالضرورة أن كل تفاصيل الجسم أو تاريخه أصبحت معروفة.\n\n## من البيانات إلى الاستنتاج\n\nيقارن الباحثون القياسات بنماذج وتوقعات بديلة، ثم يفحصون ما إذا كانت البيانات تدعم تفسيرًا واحدًا أو عدة تفسيرات. قد تتغير النتيجة عندما تتوفر ملاحظات إضافية أو عندما يعاد تحليل البيانات بطريقة أفضل. من المفيد الفصل بين ما قيس مباشرة، وما استنتجه الفريق، وما يزال فرضية تحتاج إلى اختبار. هذه الفروق مهمة خصوصًا عند قراءة العناوين التي تصف كل نتيجة جديدة بأنها اكتشاف نهائي.\n\n## لماذا نحتاج إلى تحقق مستقل؟\n\nتزداد الثقة عندما تتوافق قياسات مستقلة أو أدوات مختلفة على تفسير متقارب، أو عندما يستطيع فريق آخر إعادة تحليل البيانات والوصول إلى نتيجة مشابهة. لا يعني الاستقلال أن كل جهة تستخدم الجهاز نفسه؛ فقد توفر ملاحظات من مراصد مختلفة اختبارًا إضافيًا. وفي المقابل، قد تتفق مصادر كثيرة لأنها تنقل بيانًا صحفيًا واحدًا، فلا تعد جميعها تأكيدات مستقلة.\n\n## كيف نقرأ خبرًا فلكيًا؟\n\nابدأ باسم المهمة أو الجهاز، وتاريخ الرصد، والجهة العلمية التي نشرت البيانات. ثم اقرأ الدراسة أو الشرح الأصلي إن كان متاحًا، وتحقق من الفرق بين القياس والتفسير. ابحث عن حدود الدراسة وما يقوله الباحثون إنهم لا يعرفونه بعد. وإذا كان الخبر مبنيًا على مؤتمر صحفي فقط، فاعتبره وصفًا أوليًا حتى تظهر التفاصيل العلمية.\n\n## حدود المعرفة الحالية\n\nقد تكون البيانات حقيقية لكن تفسيرها غير محسوم، وقد يتغير تقدير المسافة أو الكتلة أو عمر الجسم مع تحسن القياسات. هذا لا ينتقص من العلم؛ بل يوضح أنه عملية تصحيح مستمرة. القراءة الدقيقة تمنح الاكتشاف أهميته دون تحويل الاحتمال إلى يقين أو تجاهل الأسئلة المفتوحة.","sources":[{"title":"Webb Space Telescope","publisher":"NASA","url":"https://science.nasa.gov/mission/webb/"},{"title":"Webb Space Science","publisher":"European Space Agency","url":"https://www.esa.int/Science_Exploration/Space_Science/Webb"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/James_Webb_Space_Telescope_Mirror.jpg?width=1200","imageAlt":"مرآة تلسكوب جيمس ويب الفضائي","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"science-test-scientific-claims-ar","section":"science","language":"ar","title":"كيف نختبر الادعاءات العلمية؟","summary":"خطوات عملية لفحص السؤال والدليل والمنهج وحدود الدراسة قبل قبول نتيجة علمية أو تداولها.","body":"## ابدأ بالسؤال المحدد\n\nالادعاء العلمي الجيد يمكن صياغته بطريقة واضحة تسمح بفحصه، مثل سؤال عن علاقة متغيرين أو أثر تدخل محدد. أما العبارات العامة من نوع أن مادة ما تعالج كل الأمراض أو أن تقنية ما تغير كل شيء، فهي واسعة ولا تحدد النتيجة التي يمكن قياسها. يساعد السؤال المحدد على اختيار نوع الدليل المناسب بدل جمع معلومات تؤيد الانطباع الأول فقط.\n\n## افحص طريقة جمع البيانات\n\nتختلف قوة الدليل بحسب تصميم الدراسة وحجم العينة وطريقة اختيار المشاركين وأدوات القياس. قد تكشف دراسة رصدية ارتباطًا بين عاملين، لكنها لا تثبت وحدها أن أحدهما سبب الآخر. أما التجارب المحكمة فقد تساعد على اختبار السببية عندما تكون مناسبة وأخلاقية، ومع ذلك تظل النتائج مرتبطة بظروف التجربة ومدى تمثيل المشاركين أو البيانات للفئة الأوسع.\n\n## لا تخلط بين الارتباط والسببية\n\nإذا ظهر أن ظاهرتين تحدثان معًا، فقد يكون هناك سبب مشترك أو عامل لم تقسه الدراسة. على سبيل المثال، قد يرتبط استخدام خدمة صحية بنتيجة أفضل لأن الأشخاص الذين يستخدمونها يختلفون أيضًا في العمر أو الدخل أو شدة الحالة. لذلك يسأل الباحثون عن العوامل المربكة، ويستخدمون طرقًا إحصائية وتصميمات بحثية مناسبة، ويقارنون النتائج بأدلة أخرى قبل تقديم تفسير سببي.\n\n## ما معنى المراجعة العلمية؟\n\nتتيح المراجعة من متخصصين فحص المنهج والتحليل والوضوح قبل النشر في كثير من المجلات. لكنها ليست ضمانًا مطلقًا للصحة؛ فقد تمر أخطاء أو تتغير المعرفة لاحقًا أو تسحب دراسة بسبب مشكلة في البيانات. من الأفضل النظر إلى المراجعة بوصفها طبقة من طبقات الفحص، إلى جانب شفافية البيانات وإمكانية إعادة التحليل وتكرار النتائج وتقييم الأدلة المتراكمة.\n\n## اقرأ النتيجة وحدودها\n\nابحث في ملخص الدراسة عن عدد المشاركين والفترة الزمنية ومقياس النتيجة وحجم الأثر، لا عن قيمة إحصائية منفردة فقط. اقرأ قسم القيود لمعرفة ما لا تستطيع الدراسة إثباته. وإذا كانت النتيجة أولية أو منشورة في صورة مسودة غير محكمة، فيجب التصريح بذلك عند نقلها وعدم تقديمها كإجماع علمي مستقر.\n\n## قارن أكثر من مصدر\n\nقد تساعد المراجعات المنهجية والتقارير العلمية الصادرة عن جهات مستقلة على معرفة ما إذا كانت النتيجة متسقة مع بقية الأدلة. تأكد من أن المصادر تتناول السؤال نفسه، وأنها لا تكرر البيان الصحفي ذاته. وإذا تعارضت النتائج، فافحص اختلاف المنهج أو السكان أو تعريف المتغيرات بدل اختيار النتيجة الأكثر إثارة.\n\n## خلاصة قابلة للتطبيق\n\nاسأل ما الذي قيس فعلًا، وكيف قيس، وما التفسيرات البديلة، وهل أمكن تكرار النتيجة. افصل بين بيانات الدراسة واستنتاج مؤلفيها والعناوين الإعلامية. بهذه الخطوات لا تحتاج إلى أن تصبح متخصصًا في كل مجال كي تكتشف المبالغة، بل يمكنك تقييم درجة الثقة بصورة منصفة والاعتراف بما لا تحسمه الأدلة بعد.","sources":[{"title":"Understanding Science","publisher":"University of California Museum of Paleontology","url":"https://undsci.berkeley.edu/"},{"title":"Science and Engineering Indicators","publisher":"National Science Foundation","url":"https://ncses.nsf.gov/indicators"}],"imageUrl":"https://commons.wikimedia.org/wiki/Special:FilePath/Microscope.jpg?width=1200","imageAlt":"مجهر يستخدم في البحث العلمي","createdAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","updatedAt":"strftime('%Y-%m-%dT%H:%M:%fZ','now')","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"politics-public-consultation-en","section":"politics","language":"en","title":"How public consultation can improve decisions","summary":"A practical guide to consultation, public evidence, representation and checking whether participation changed a policy outcome.","body":"## Consultation is a process, not a checkbox\n\nPublic consultation gives people who may be affected by a decision a chance to explain needs, identify overlooked impacts and compare possible solutions. A meeting or online form alone does not prove that participation was meaningful. The process should state what decision is open, who has authority to make it, which options remain possible and when contributions will be considered. If the decision has already been made, the institution should explain what feedback can still change and what is no longer negotiable.\n\n## Define the question before collecting views\n\nA clear question helps participants respond to the real problem instead of guessing what officials want to hear. For example, a transport consultation might ask how a route affects travel time, access for disabled passengers, safety, cost and connections with other services. Different groups can experience the same proposal differently, so organisers should publish the scope, the evidence already available and the criteria that will be used to compare options. This makes the process easier to understand and reduces the risk that loud or well-resourced voices dominate by default.\n\n## Make participation accessible\n\nPeople cannot contribute if the process is available only at a time, location or format that excludes them. Accessible consultation can combine written submissions, public meetings, translated material, clear summaries and formats suitable for people with disabilities. Organisers should explain how personal information will be handled and avoid collecting unnecessary sensitive details. Outreach should aim to hear from affected communities, not only from people who routinely attend public meetings or already know how government procedures work.\n\n## Separate evidence from preference\n\nSubmissions may contain personal experiences, predictions, values and factual claims. Each can be useful, but they answer different questions. A personal account may reveal a barrier that aggregate data misses; a statistical claim may need a source and a defined time period; a preference explains which trade-off a participant considers acceptable. Decision makers should record these differences rather than count every statement as if it were the same kind of evidence. Independent data and transparent methods can help test claims without dismissing lived experience.\n\n## Show what happened after consultation\n\nA credible process closes the loop. The responsible institution should publish a summary of themes, identify which proposals were adopted or rejected and give reasons for important choices. Where feasible, it should show how the final decision differs from the initial proposal. A response that merely thanks participants without explaining the outcome makes accountability difficult. A public record also allows later reviewers to compare promises with implementation and identify whether the consultation affected the decision in practice.\n\n## How readers can assess quality\n\nLook for the original consultation notice, the rules for submitting views, the evidence supplied to participants and the published response. Check dates and jurisdiction because similar policies can follow different legal processes in different places. Compare the final decision with the options that were originally open, and distinguish an official explanation from an independent evaluation. International guidance can help frame questions, but local law determines the institution’s formal duties. Consultation is strongest when the scope is honest, access is broad, evidence is considered fairly and the final reasoning is visible.","sources":[{"publisher":"OECD","title":"Open government and public participation","url":"https://www.oecd.org/en/topics/open-government.html"},{"publisher":"United Nations","title":"Democracy and participation","url":"https://www.un.org/en/global-issues/democracy"}],"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/0/05/UN_General_Assembly_hall.jpg","imageAlt":"The United Nations General Assembly hall","createdAt":"CURRENT_TIMESTAMP","updatedAt":"CURRENT_TIMESTAMP","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"politics-public-consultation-ar","section":"politics","language":"ar","title":"كيف تحسّن المشاورات العامة القرارات","summary":"دليل عملي لفهم المشاورات العامة، والأدلة التي يقدمها الناس، وتمثيل الفئات المتأثرة، وقياس أثر المشاركة في القرار النهائي.","body":"## المشاورة عملية وليست إجراءً شكليًا\n\nتمنح المشاورات العامة الأشخاص المتأثرين بقرار ما فرصة لشرح احتياجاتهم، والتنبيه إلى آثار لم تُدرس، ومقارنة الحلول الممكنة. لكن عقد اجتماع أو نشر نموذج إلكتروني لا يثبت وحده أن المشاركة كانت مؤثرة. ينبغي توضيح القرار المطروح، والجهة التي تملك صلاحية اتخاذه، والخيارات التي ما زالت مفتوحة، والموعد الذي ستُدرس فيه المشاركات. وإذا كان القرار قد حُسم بالفعل، فعلى الجهة المسؤولة أن تشرح ما الذي يمكن أن يتغير وما الذي لم يعد قابلًا للتعديل.\n\n## حدّد السؤال قبل جمع الآراء\n\nيساعد السؤال الواضح المشاركين على مناقشة المشكلة الفعلية بدلًا من محاولة تخمين ما تريد الجهة سماعه. فقد تتناول مشاورة عن مسار نقل عام زمن الرحلة، وإتاحة الخدمة لذوي الإعاقة، والسلامة، والتكلفة، والربط بوسائل النقل الأخرى. وقد تتأثر الفئات المختلفة بالمقترح نفسه بطرق متباينة؛ لذلك ينبغي نشر نطاق المشاورة والبيانات المتاحة والمعايير التي ستُستخدم للمقارنة. يوضح ذلك طريقة اتخاذ القرار ويحد من هيمنة الأصوات الأعلى أو الأكثر قدرة على الوصول.\n\n## اجعل المشاركة متاحة للجميع\n\nقد يُستبعد بعض الناس إذا كانت المشاركة متاحة في وقت أو مكان أو صيغة لا تناسب ظروفهم. ويمكن الجمع بين المذكرات المكتوبة والاجتماعات العامة والملخصات الواضحة والترجمة والصيغ المناسبة للأشخاص ذوي الإعاقة. كما ينبغي شرح كيفية التعامل مع البيانات الشخصية وتجنب جمع معلومات حساسة لا حاجة إليها. ويجب أن تستهدف الدعوة المجتمعات المتأثرة فعلًا، لا الأشخاص الذين اعتادوا حضور الاجتماعات أو يعرفون مسبقًا إجراءات المؤسسات العامة.\n\n## فرّق بين الدليل والتفضيل\n\nقد تتضمن المشاركات تجارب شخصية أو توقعات أو قيمًا أو ادعاءات واقعية. لكل نوع منها فائدة، لكنه لا يجيب عن السؤال نفسه. فقد تكشف تجربة فردية عائقًا لا يظهر في المتوسطات الإحصائية، بينما يحتاج الادعاء الرقمي إلى مصدر وفترة زمنية محددة، ويشرح التفضيل نوع المفاضلة التي يقبلها صاحبه. من الأفضل تسجيل هذه الفروق بدل التعامل مع كل عبارة كأنها دليل من النوع ذاته. ويمكن للبيانات المستقلة والمنهجيات المعلنة اختبار الادعاءات من دون التقليل من قيمة الخبرة المعيشة.\n\n## انشر ما حدث بعد المشاورة\n\nتكتمل العملية الموثوقة عندما تنشر الجهة المسؤولة خلاصة الموضوعات التي تكررت، وتوضح المقترحات التي قبلتها أو رفضتها وأسباب القرارات المهمة. وحيثما أمكن، ينبغي بيان الاختلاف بين المقترح الأولي والقرار النهائي. أما شكر المشاركين من دون شرح النتيجة فيجعل المساءلة صعبة. كما يسمح السجل العام بمقارنة الوعود بالتنفيذ لاحقًا، ومعرفة ما إذا كانت المشاورات قد أثرت فعلًا في القرار أو بقيت خطوة شكلية.\n\n## كيف تقيّم جودة المشاركة؟\n\nابحث عن إعلان المشاورة الأصلي، وقواعد إرسال الآراء، والأدلة التي أتيحت للمشاركين، ورد الجهة النهائي. تحقّق من التواريخ والنطاق القانوني، لأن الإجراءات قد تختلف من دولة إلى أخرى حتى عندما تتشابه السياسات. قارن القرار النهائي بالخيارات التي كانت متاحة في البداية، وميّز بين تفسير المؤسسة والتقييم المستقل. تساعد الإرشادات الدولية على صياغة أسئلة جيدة، لكن القانون المحلي هو الذي يحدد الواجبات الرسمية. وتكون المشاورة أقوى عندما يكون نطاقها صريحًا، والوصول إليها واسعًا، وفحص الأدلة عادلًا، وأسباب القرار معلنة.","sources":[{"publisher":"منظمة التعاون الاقتصادي والتنمية","title":"الحكومة المنفتحة والمشاركة العامة","url":"https://www.oecd.org/en/topics/open-government.html"},{"publisher":"الأمم المتحدة","title":"الديمقراطية والمشاركة","url":"https://www.un.org/en/global-issues/democracy"}],"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/0/05/UN_General_Assembly_hall.jpg","imageAlt":"قاعة الجمعية العامة للأمم المتحدة","createdAt":"CURRENT_TIMESTAMP","updatedAt":"CURRENT_TIMESTAMP","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"travel-responsible-heritage-en","section":"travel","language":"en","title":"How to visit heritage places responsibly","summary":"How to plan visits to historic places while protecting fragile sites, respecting local communities and separating evidence from tourist myths.","body":"## Heritage is more than a photograph\n\nHistoric places hold physical evidence of how people lived, traded, built, worshipped and adapted to changing environments. Their value may include architecture, archaeological layers, living traditions and meanings that remain important to local communities. A responsible visit begins by learning what a place represents and why some areas may be closed or access may be limited. A site is not simply a backdrop for photographs: it is a finite resource that can be damaged by touching surfaces, leaving waste, climbing on structures or ignoring barriers put in place for protection.\n\n## Check the rules before arriving\n\nEntry conditions can change with conservation work, weather, religious events, crowd management or security requirements. Consult the official site authority or heritage organisation before travel, and confirm opening hours, ticket rules, accessibility, photography restrictions and permitted routes. A booking page or social post may not reflect a later closure, so check the latest notice when the visit matters. Keep a flexible plan and follow instructions from authorised staff rather than relying on unverified advice from strangers or old travel blogs.\n\n## Respect people who live and work there\n\nMany heritage places are also neighbourhoods, places of worship, working landscapes or sources of income for local residents. Ask before photographing people, dress appropriately for the setting, keep noise low and avoid blocking doorways or everyday routes. Buy goods and services transparently, agree prices before a service begins and prefer local businesses that explain what they provide. Responsible travel is not about treating every local interaction as a performance for visitors; it means recognising that the site remains part of someone else’s daily life after a tourist leaves.\n\n## Reduce pressure on fragile places\n\nStay on marked paths, do not remove stones or artefacts, and never write on walls or monuments. Follow rules about drones, flash photography and food, and carry rubbish out when bins are unavailable. Large crowds can wear down surfaces, disturb wildlife and strain water or sanitation systems. When possible, visit at less crowded times, use authorised guides and choose transport options that reduce unnecessary congestion. These small choices cannot solve every conservation challenge, but they lower avoidable damage and help staff protect the site for future visitors.\n\n## Separate established history from attractive stories\n\nPopular destinations often attract dramatic legends, simplified timelines and claims that spread faster than the evidence. Read the interpretation provided by recognised heritage bodies and compare it with museum, archaeological or academic material when a claim seems extraordinary. Ask whether a date is supported by excavation, inscriptions, documents or later tradition, and whether experts disagree. Uncertainty is normal in historical research. A careful guide should explain what is known, what is inferred and what remains debated instead of presenting every story as settled fact.\n\n## Make the trip useful and fair\n\nBefore booking, consider whether the operator follows site rules, explains cancellation terms and provides accurate information about access and safety. Carry water where permitted, plan for heat and long walks, and keep emergency contacts available. If an area is restricted, treat the restriction as part of conservation rather than an invitation to find another entrance. After the visit, share practical information responsibly and avoid posting directions to sensitive locations that are vulnerable to damage. UNESCO’s heritage framework and responsible tourism guidance offer useful starting points, while local authorities set the rules that visitors must follow at each place.","sources":[{"publisher":"UNESCO World Heritage Centre","title":"World Heritage and its protection","url":"https://whc.unesco.org/en/about/"},{"publisher":"UN Tourism","title":"Sustainable tourism","url":"https://www.unwto.org/sustainable-development"}],"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/a/a0/Great_Pyramid_of_Giza.jpg","imageAlt":"The Great Pyramid of Giza","createdAt":"CURRENT_TIMESTAMP","updatedAt":"CURRENT_TIMESTAMP","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"travel-responsible-heritage-ar","section":"travel","language":"ar","title":"كيف تزور المواقع التراثية بمسؤولية","summary":"إرشادات للتخطيط لزيارة المواقع التاريخية مع حماية الأماكن الهشة واحترام السكان المحليين والتمييز بين الحقائق والحكايات السياحية.","body":"## التراث أكبر من صورة تذكارية\n\nتحفظ المواقع التاريخية أدلة مادية على كيفية عيش الناس وتبادلهم وبنائهم وعبادتهم وتكيفهم مع تغير البيئة. وقد تشمل قيمتها العمارة والطبقات الأثرية والتقاليد الحية والمعاني التي ما زالت مهمة للمجتمعات المحلية. تبدأ الزيارة المسؤولة بفهم ما يمثله المكان وسبب إغلاق بعض المناطق أو تقييد الوصول إليها. فالموقع ليس خلفية للتصوير فقط؛ بل مورد محدود يمكن أن يتضرر بلمس الأسطح أو ترك المخلفات أو تسلق المنشآت أو تجاهل الحواجز الموضوعة لحمايته.\n\n## تحقّق من القواعد قبل الوصول\n\nقد تتغير شروط الدخول بسبب أعمال الترميم أو الطقس أو المناسبات الدينية أو تنظيم الحشود أو المتطلبات الأمنية. راجع الجهة الرسمية المسؤولة عن الموقع قبل السفر، وتأكد من مواعيد الزيارة والتذاكر وإتاحة الوصول وقيود التصوير والمسارات المسموح بها. قد لا تعكس صفحة حجز أو منشور قديم إغلاقًا أُعلن لاحقًا، لذلك افحص أحدث التنبيهات عندما تكون الزيارة مهمة. ضع خطة مرنة واتبع تعليمات الموظفين المخولين بدل الاعتماد على نصائح مجهولة أو مدونات سفر قديمة.\n\n## احترم السكان والعاملين في المكان\n\nتكون مواقع التراث في أحيان كثيرة أحياء سكنية أو أماكن عبادة أو أراضي عمل ومصادر دخل للسكان. استأذن قبل تصوير الأشخاص، وراعِ طبيعة المكان في الملابس، وخفّض الضوضاء، ولا تسد المداخل أو المسارات اليومية. تعامل بوضوح عند شراء الخدمات والمنتجات، واتفق على السعر قبل بدء الخدمة، وفضّل الأنشطة المحلية التي تشرح ما تقدمه. لا تعني السياحة المسؤولة تحويل كل تفاعل محلي إلى مشهد للزائر؛ بل تعني إدراك أن المكان جزء من حياة الآخرين اليومية بعد مغادرة السائح.\n\n## خفّف الضغط على المواقع الهشة\n\nالتزم بالمسارات المحددة، ولا تجمع الحجارة أو القطع الأثرية، ولا تكتب على الجدران أو الآثار. اتبع قواعد الطائرات المسيّرة والتصوير بالفلاش والطعام، وخذ مخلفاتك معك عندما لا تتوفر حاويات. قد تؤدي الحشود الكبيرة إلى تآكل الأسطح وإزعاج الحياة البرية وزيادة الضغط على المياه والصرف الصحي. إذا أمكن، اختر أوقاتًا أقل ازدحامًا، واستعن بمرشدين مرخصين، واستخدم وسائل نقل تقلل الازدحام غير الضروري. لا تحل هذه الخطوات كل تحديات الحماية، لكنها تقلل الأضرار الممكن تجنبها.\n\n## ميّز التاريخ الموثق عن القصص الجذابة\n\nتجذب الوجهات الشهيرة الأساطير الدرامية والخطوط الزمنية المبسطة والادعاءات التي تنتشر أسرع من الأدلة. اقرأ المعلومات التي تقدمها الجهات التراثية المعروفة، وقارنها بمواد المتاحف أو الدراسات الأثرية والأكاديمية عندما يبدو الادعاء استثنائيًا. اسأل هل يستند التاريخ إلى حفريات أو نقوش أو وثائق أم إلى رواية متأخرة، وهل يوجد خلاف بين المختصين. عدم اليقين أمر طبيعي في البحث التاريخي؛ وعلى الدليل الجيد أن يوضح المعروف والمستنتج وما لا يزال محل نقاش بدل تقديم كل حكاية كحقيقة نهائية.\n\n## اجعل الرحلة نافعة وعادلة\n\nقبل الحجز، تحقّق من التزام مقدم الخدمة بقواعد الموقع، ووضوح شروط الإلغاء، ودقة المعلومات عن الوصول والسلامة. خطط للماء والحرارة والمشي الطويل، واحتفظ بوسائل الاتصال للطوارئ. إذا كانت منطقة مغلقة، فاعتبر ذلك جزءًا من الحماية لا دعوة للبحث عن مدخل بديل. وبعد الزيارة، شارك المعلومات العملية بمسؤولية ولا تنشر إرشادات لمواقع حساسة قد تتعرض للتلف. يوفر إطار التراث العالمي وإرشادات السياحة المسؤولة نقطة بداية مفيدة، بينما تحدد الجهات المحلية القواعد التي يجب اتباعها في كل موقع.","sources":[{"publisher":"مركز التراث العالمي باليونسكو","title":"التراث العالمي وحمايته","url":"https://whc.unesco.org/en/about/"},{"publisher":"الأمم المتحدة للسياحة","title":"السياحة المستدامة","url":"https://www.unwto.org/sustainable-development"}],"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/a/a0/Great_Pyramid_of_Giza.jpg","imageAlt":"الهرم الأكبر في الجيزة","createdAt":"CURRENT_TIMESTAMP","updatedAt":"CURRENT_TIMESTAMP","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"egypt-household-surveys-daily-life-en","section":"egypt","language":"en","title":"Understanding household surveys and daily life in Egypt","summary":"A source-led guide to what Egypt’s household income, expenditure and consumption survey can tell us about living standards and public services, and what dated data cannot establish about current costs.","body":"## Why household surveys matter\n\nHousehold surveys describe parts of daily life through the resources families receive and the goods and services they use. They differ from a price list or one person’s experience: a survey collects information from a sample under a documented method. Results can help researchers study living standards and consumption patterns, but they do not describe every family identically and are not a live estimate of what households spend today.\n\n## What Egypt’s survey measures\n\nThe CAPMAS catalog describes Egypt’s 2021 Survey of Income, Expenditure and Consumption as a household study covering income, spending, consumption, housing conditions and demographic characteristics. It states that data collection ran from January through December 2021 and that the survey covered 25,600 households. The reference year, sample design and definitions are essential to interpreting any table; they set limits on the population and period the figures can represent.\n\n## Reading cost-of-living evidence\n\nHousehold budgets vary with family size, location, employment, housing arrangements and access to services. A national average can summarize a population while concealing differences between groups. Readers should check the indicator definition, weights, price reference period and available breakdowns. An older survey cannot by itself establish a current market price or the cost of a basket of goods in 2026, and comparisons across years require comparable methods and careful treatment of inflation.\n\n## Connecting statistics with public services\n\nHousehold data are one part of understanding social policy. The World Bank’s Egypt materials describe support for social safety-net programmes, including Takaful and Karama, and efforts to improve targeting and delivery. This documents programme design and support; it does not prove that every household receives assistance or that a programme alone explains changes in living standards. Assessing outcomes requires dated coverage figures, eligibility rules, implementation information and independent evaluation.\n\n## What the evidence does not establish\n\nA survey can show patterns but does not automatically explain their causes. Changes in spending may reflect prices, household composition, income, availability or measurement. Before comparing two years, check whether definitions and collection methods are comparable and whether inflation has been considered. A precise claim about present conditions needs a current, traceable source rather than an old survey presented without its date.\n\n## A practical way to use the data\n\nStart with the original CAPMAS documentation, record the survey year and population, and compare it with later official statistics and independent analysis. Use World Bank programme material to understand the stated design of social protection initiatives, not as a substitute for household-level outcome data. Separating these evidence types helps readers understand everyday life in Egypt without turning dated statistics into unsupported claims about the present.","sources":[{"publisher":"Central Agency for Public Mobilization and Statistics (CAPMAS)","title":"Survey of Income, Expenditure and Consumption 2021","url":"https://www.censusinfo.capmas.gov.eg/en/index.php/catalog/747"},{"publisher":"World Bank","title":"Egypt country overview and social protection programmes","url":"https://www.worldbank.org/ext/en/country/egypt?section=6076"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/egypt.svg","imageAlt":"Understanding household surveys and daily life in Egypt","createdAt":"CURRENT_TIMESTAMP","updatedAt":"CURRENT_TIMESTAMP","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"egypt-household-surveys-daily-life-ar","section":"egypt","language":"ar","title":"كيف تساعد مسوح الأسر على فهم الحياة اليومية في مصر؟","summary":"دليل قائم على المصادر لفهم ما توضحه مسوح دخل الأسر وإنفاقها واستهلاكها عن مستويات المعيشة والخدمات العامة، وما لا يجوز استنتاجه من بيانات قديمة.","body":"## لماذا نحتاج إلى مسوح الأسر؟\n\nتساعد مسوح الأسر على وصف جوانب من الحياة اليومية من خلال الدخل والإنفاق والاستهلاك والخدمات التي تستخدمها العائلات. وهي تختلف عن قائمة أسعار أو تجربة فردية؛ إذ تجمع بيانات من عينة محددة وفق منهج معلن، ثم تُستخدم النتائج لفهم أنماط أوسع. ومع ذلك، لا تمثل النتائج وصفًا مطابقًا لكل أسرة، ولا تصلح وحدها لتحديد تكلفة المعيشة في الوقت الحالي.\n\n## ماذا يقيس المسح المصري؟\n\nيوضح فهرس الجهاز المركزي للتعبئة العامة والإحصاء أن مسح الدخل والإنفاق والاستهلاك لعام 2021 يتناول دخل الأسر وإنفاقها واستهلاكها وظروف السكن والخصائص الديموغرافية. ويذكر الفهرس أن جمع البيانات امتد من يناير إلى ديسمبر 2021 وشمل عينة من 25,600 أسرة. تساعد هذه المعلومات على تفسير الجداول بصورة صحيحة؛ فسنة القياس وحجم العينة وطريقة اختيارها تحدد نطاق الاستنتاجات التي يمكن دعمها.\n\n## كيف نقرأ بيانات تكلفة المعيشة؟\n\nتختلف ميزانية الأسرة باختلاف عدد أفرادها ومكان السكن والعمل وترتيبات السكن وإمكانية الوصول إلى الخدمات. وقد يخفي المتوسط فروقًا كبيرة بين الفئات والمناطق. لذلك ينبغي قراءة النتائج مع تعريفات المؤشرات والأوزان والفترة المرجعية للأسعار والتقسيمات المتاحة بحسب خصائص الأسر. ولا يصح تقديم نتيجة مسح قديم باعتبارها سعرًا حاليًا، كما تتطلب المقارنة بين الأعوام التأكد من تقارب المنهجيات ومراعاة أثر التضخم.\n\n## الربط بين الإحصاءات والخدمات العامة\n\nتمثل بيانات الأسر جانبًا واحدًا من فهم السياسات الاجتماعية. وتشير مواد البنك الدولي عن مصر إلى دعم برامج شبكات الأمان الاجتماعي، ومنها تكافل وكرامة، وإلى جهود لتحسين استهداف المساعدات وتنفيذها. لكن وصف برنامج أو أهدافه لا يثبت أن كل أسرة تستفيد منه، ولا يثبت أن البرنامج وحده يفسر تغير مستوى المعيشة. يتطلب تقييم النتائج بيانات مؤرخة عن التغطية وشروط الاستحقاق والتنفيذ وتقييمًا مستقلًا للأثر.\n\n## ما الذي لا تثبته البيانات وحدها؟\n\nيمكن للمسح أن يبين أنماطًا، لكنه لا يحدد أسبابها تلقائيًا. فقد تتأثر تغيرات الإنفاق بالأسعار أو حجم الأسرة أو الدخل أو توافر السلع أو طريقة القياس. وقبل مقارنة عامين، يجب التأكد من تقارب التعريفات والمنهجيات ومراعاة أثر التضخم. وإذا عرض ادعاء رقمًا دقيقًا عن الوضع الحالي من دون تاريخ نشر أو جدول يمكن تتبعه، فهناك حاجة إلى دليل إضافي.\n\n## طريقة عملية للاستفادة من النتائج\n\nابدأ بوثائق المسح الأصلية الصادرة عن الجهاز المركزي للتعبئة العامة والإحصاء، وسجل سنة البيانات والفئة التي تمثلها، ثم قارنها بإحصاءات رسمية أحدث وتحليلات مستقلة. واستخدم مواد البنك الدولي لفهم تصميم برامج الحماية الاجتماعية المعلن، لا بديلًا عن بيانات النتائج على مستوى الأسر. يساعد الفصل بين هذه الأنواع من الأدلة على فهم الحياة اليومية في مصر من دون تحويل أرقام قديمة إلى ادعاءات غير مدعومة عن الحاضر.","sources":[{"publisher":"الجهاز المركزي للتعبئة العامة والإحصاء (CAPMAS)","title":"مسح الدخل والإنفاق والاستهلاك لعام 2021","url":"https://www.censusinfo.capmas.gov.eg/en/index.php/catalog/747"},{"publisher":"البنك الدولي","title":"مواد مصر وبرامج الحماية الاجتماعية","url":"https://www.worldbank.org/ext/en/country/egypt?section=6076"}],"imageUrl":"https://bayan.tahaomar411.workers.dev/sections/egypt.svg","imageAlt":"كيف تساعد مسوح الأسر على فهم الحياة اليومية في مصر؟","createdAt":"CURRENT_TIMESTAMP","updatedAt":"CURRENT_TIMESTAMP","status":"PUBLISHED","fallbackEvidence":"verified"},{"section":"people","createdAt":"2026-10-21T00:00:00Z","updatedAt":"2026-10-21T00:00:00Z","imageUrl":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Taha_hussein.jpg/800px-Taha_hussein.jpg","fallbackEvidence":"verified","status":"PUBLISHED","slug":"who-is-taha-hussein-ar","language":"ar","title":"طه حسين: عميد الأدب العربي ومشروعه الفكري","summary":"سيرة موثقة للأديب والناقد المصري طه حسين، تتناول تعليمه ومساره الجامعي وأعماله وإسهامه في النقاش حول الأدب والتعليم، مع فصل الوقائع التاريخية عن التقييم النقدي.","body":"## خلاصة\nطه حسين (1889–1973) أديب وناقد ومفكر مصري يُعرف بلقب «عميد الأدب العربي». جمع في مسيرته بين البحث الأكاديمي والكتابة الأدبية والنقاش العام حول التعليم والثقافة. وتُقرأ مكانته من خلال كتبه ومقالاته ومواقفه الفكرية، مع ضرورة التمييز بين الوقائع التي تثبتها المراجع والتفسيرات التي يقدمها النقاد لتأثيره.\n\n## النشأة والتعليم\nوُلد طه حسين في صعيد مصر وفقد بصره في طفولته. درس في الأزهر، ثم التحق بالجامعة المصرية عند تأسيسها في مطلع القرن العشرين، حيث اتجه إلى الدراسة المنهجية للتاريخ والأدب. وقد مثّل انتقاله بين مؤسسات التعليم التقليدي والجامعة الحديثة جزءًا مهمًا من تجربته الفكرية، من دون اختزالها في قصة نجاح فردية فقط.\n\n## الدراسة في فرنسا والعمل الأكاديمي\nتابع دراسته في فرنسا بجامعة السوربون، واحتك بالمناهج التاريخية والنقدية الأوروبية. أسهم هذا التكوين في تطوير طريقته في قراءة النصوص القديمة ومناقشة مصادرها، لكنه لم يكن مجرد نقل آلي لمنهج أجنبي؛ فقد أثارت تطبيقاته أسئلة عن العلاقة بين التراث والمناهج الحديثة وحدود التأويل. وتُظهر سيرته الأكاديمية أن البحث عنده ارتبط بالجدل العام حول معنى المعرفة ومصادرها.\n\n## الكتابة والجدل النقدي\nمن أشهر أعماله «الأيام»، وهي سيرة ذاتية أدبية تسرد جانبًا من طفولته وتعليمه، و«مستقبل الثقافة في مصر» الذي ناقش فيه التعليم والهوية الثقافية، إلى جانب دراساته ومقالاته الأدبية. أثار كتابه «في الشعر الجاهلي» عام 1926 جدلًا واسعًا بسبب أسئلته حول الروايات الشعرية القديمة وطرق التحقق منها. ومن الأدق قراءة ذلك الجدل ضمن سياقه التاريخي، لا الاكتفاء بشعارات مؤيدة أو معارضة.\n\n## التعليم والشأن العام\nتولى طه حسين مسؤوليات أكاديمية وثقافية، وشغل منصب وزير المعارف في مصر عام 1950. ارتبط اسمه بالدفاع عن توسيع فرص التعليم، وبالعبارة المشهورة التي تشبّه التعليم بالماء والهواء. وينبغي عند وصف السياسات التي نُفذت في عهده التفريق بين الدعوة الفكرية، والقرارات الحكومية المحددة، والتطورات التعليمية التي امتدت عبر سنوات وحكومات مختلفة.\n\n## كيف نقيّم إرثه؟\nيمكن دراسة إرث طه حسين عبر قراءة نصوصه الأصلية ومقارنتها بدراسات تاريخ الأدب والتعليم في مصر. بعض أحكامه النقدية ما زالت موضوع نقاش أكاديمي، وهذا أمر طبيعي في تاريخ الفكر؛ فالمكانة الثقافية لا تعني أن كل رأي يصدر عن صاحبها حقيقة نهائية. توفر المراجع المرجعية مدخلًا للتحقق من التواريخ والأعمال، بينما يحتاج تقييم أفكاره إلى قراءة السياق والحجج كاملة.","sources":[{"title":"Taha Hussein — biography","publisher":"Encyclopaedia Britannica","url":"https://aucpress.com/author/taha-hussein/"},{"title":"Taha Hussein","publisher":"The American University in Cairo","url":"https://www.encyclopedia.com/history/encyclopedias-almanacs-transcripts-and-maps/taha-husayn"}],"imageAlt":"طه حسين، الأديب والناقد المصري"},{"section":"people","createdAt":"2026-10-21T00:00:00Z","updatedAt":"2026-10-21T00:00:00Z","imageUrl":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Taha_hussein.jpg/800px-Taha_hussein.jpg","fallbackEvidence":"verified","status":"PUBLISHED","slug":"who-is-taha-hussein-en","language":"en","title":"Taha Hussein: Dean of Arabic Literature and Intellectual Pioneer","summary":"A sourced profile of Egyptian writer and critic Taha Hussein, covering his education, academic career, major works, and arguments about literature and public education.","body":"## Overview\nTaha Hussein (1889–1973) was an Egyptian writer, literary critic, and public intellectual widely known as the “Dean of Arabic Literature.” His career connected academic research with essays, autobiographical writing, and public debate about education and culture. His legacy is best assessed by separating verifiable biographical facts from critical interpretations of his influence.\n\n## Early life and education\nHussein was born in Upper Egypt and lost his eyesight during childhood. He studied at Al-Azhar before attending the Egyptian University soon after its establishment in the early twentieth century. Moving between traditional learning and a modern university shaped his intellectual experience, but his life should not be reduced to a simple inspirational narrative; his education also reflected wider changes in Egyptian institutions and public culture.\n\n## Study in France and academic work\nHe continued his studies in France at the Sorbonne and encountered European historical and critical methods. This experience informed his approach to older texts and the examination of sources. It was not simply the importation of a foreign method: his work raised questions about how modern scholarship could engage with Arabic literary heritage, and about the limits and consequences of particular interpretations. His academic career became part of a broader debate over evidence and knowledge.\n\n## Writing and critical controversy\nAmong Hussein’s best-known works is “The Days” (Al-Ayyam), an autobiographical literary account of his childhood and education. “The Future of Culture in Egypt” explored education and cultural identity, while his essays and literary studies addressed Arabic literature and its history. His 1926 book “On Pre-Islamic Poetry” provoked intense debate because it questioned received accounts of early Arabic poetry and the methods used to assess them. The controversy is most accurately understood in its historical setting rather than through slogans for or against him.\n\n## Education and public service\nHussein held academic and cultural leadership roles and served as Egypt’s minister of education in 1950. He became closely associated with the argument that education should be broadly accessible, often summarized in the phrase that education is as essential as water and air. Descriptions of policy during his tenure should distinguish his intellectual advocacy from specific government decisions and from educational changes that unfolded across multiple years and administrations.\n\n## Assessing his legacy\nReaders can examine Hussein’s legacy by consulting his original works alongside scholarship on modern Arabic literature and the history of education in Egypt. Some of his critical judgments remain subjects of academic debate, as is expected of influential intellectual work. Cultural stature does not make every argument conclusive; careful assessment requires the full text, its historical context, and the evidence offered for each interpretation.","sources":[{"title":"Taha Hussein — biography","publisher":"Encyclopaedia Britannica","url":"https://aucpress.com/author/taha-hussein/"},{"title":"Taha Hussein","publisher":"The American University in Cairo","url":"https://www.encyclopedia.com/history/encyclopedias-almanacs-transcripts-and-maps/taha-husayn"}],"imageAlt":"Taha Hussein, Egyptian writer and literary critic"},{"slug":"who-is-mohamed-salah-ar","section":"people","language":"ar","title":"محمد صلاح: السيرة والمسيرة والأرقام القياسية","summary":"سيرة موثقة للاعب المصري محمد صلاح، من بداياته في نجريج والمقاولون العرب إلى مسيرته الأوروبية ونجاحاته مع ليفربول، مع توضيح الأرقام بحسب المصدر والموسم.","body":"## خلاصة\n\nمحمد صلاح حامد محروس غالي لاعب كرة قدم مصري، وُلد في 15 يونيو 1992، واشتهر بقدرته على اللعب مهاجمًا من الجهة اليمنى وبالسرعة والتحرك دون كرة والإنهاء بالقدم اليسرى. بدأ مسيرته الاحترافية في مصر، ثم انتقل إلى أوروبا، وأصبح أحد أبرز اللاعبين المصريين والأفارقة في كرة القدم الحديثة. وتوثق صفحات الأندية والبطولات مسيرته وأرقامه، بينما تساعد التغطية الصحفية المستقلة على وضع هذه الإنجازات في سياقها.\n\n## النشأة والبدايات\n\nنشأ صلاح في قرية نجريج بمحافظة الغربية في دلتا النيل. التحق بفرق الناشئين في نادي المقاولون العرب في القاهرة وهو في سن مبكرة، وكانت الرحلات المتكررة من قريته إلى التدريبات جزءًا من مسيرته الأولى. شارك مع الفريق الأول للمقاولون العرب قبل انتقاله إلى بازل السويسري عام 2012، حيث بدأ يلفت الانتباه في المنافسات الأوروبية. وتورد تقارير BBC Sport عن نشأته تفاصيل عن مركز الشباب في نجريج ودور الأسرة والمدربين الأوائل؛ ينبغي التعامل مع الروايات الشخصية المنقولة بوصفها شهادات صحفية لا بديلًا عن السجلات الرسمية.\n\n## المسيرة الاحترافية والتحول الأوروبي\n\nفي بازل، شارك صلاح في المنافسات المحلية والأوروبية، وساعدته مبارياته أمام أندية إنجليزية على جذب اهتمام أندية أكبر. انتقل إلى تشيلسي في 2014، ثم خاض فترات إعارة مع فيورنتينا وروما في إيطاليا قبل أن ينضم إلى روما بصورة دائمة. أعادت هذه المرحلة بناء حضوره في كرة القدم الأوروبية، وأظهر خلالها تطورًا في التسجيل وصناعة الفرص.\n\nانضم صلاح إلى ليفربول في يونيو 2017. وفي موسمه الأول سجل 44 هدفًا في جميع المسابقات بحسب سجل النادي، ثم ساهم في فوز الفريق بدوري أبطال أوروبا عام 2019، وكأس العالم للأندية وكأس السوبر الأوروبي في العام نفسه. وفاز ليفربول بالدوري الإنجليزي الممتاز في موسمي 2019–2020 و2024–2025، إلى جانب كأس الاتحاد الإنجليزي وكأس الرابطة في فترات وجوده. انتهت مرحلته مع ليفربول بنهاية موسم 2025–2026 وفق سجل النادي المنشور في يوليو 2026؛ ولا يحدد هذا الملف ناديه التالي.\n\n## الألقاب والأرقام القياسية الموثقة\n\nتسجل صفحة ليفربول التاريخية المنشورة في 2026 أن صلاح خاض 442 مباراة مع النادي وسجل 257 هدفًا وصنع 120 هدفًا في جميع المسابقات، وأنه كان هداف ليفربول التاريخي في الدوري الإنجليزي الممتاز. كما تذكر أربعة ألقاب للحذاء الذهبي في الدوري الإنجليزي، وثلاث جوائز من رابطة كتاب كرة القدم، وثلاث جوائز من رابطة اللاعبين المحترفين، وفق تصنيف النادي. تختلف الأرقام باختلاف تاريخ التحديث وما إذا كان الإحصاء يشمل كل المسابقات أو الدوري فقط؛ لذلك يجب إرفاق الموسم ونطاق المسابقة عند نقل أي رقم.\n\n## الأثر الرياضي والمجتمعي\n\nتجاوز أثر صلاح حدود النادي والمنتخب؛ إذ أصبح شخصية رياضية معروفة في مصر والعالم العربي وبين جماهير كرة القدم الدولية. وتتناول تقارير BBC Sport صلته بنجريج، وتأثير نجاحه في طموحات الناشئين، وحضوره في نقاشات الهوية والتمثيل المجتمعي. هذه قراءة للأثر العام وليست مقياسًا إحصائيًا، وينبغي نسب الآراء والتقييمات إلى أصحابها وعدم تحويلها إلى إجماع مفترض.\n\n## كيف نقرأ مسيرته بدقة؟\n\nللتأكد من رقم أو لقب، تُقدَّم سجلات الدوري والبطولات والنادي على الملخصات المتداولة، وتُقارن التغطية الصحفية المستقلة بالسجلات الأصلية. يجب التمييز بين أهداف الدوري والأهداف في جميع المسابقات، وبين الألقاب الجماعية والجوائز الفردية، وتحديد تاريخ كل إحصاء. هذا الملف يصف مسيرة موثقة حتى نهاية موسم 2025–2026، ولا يخمّن وجهة صلاح التالية أو أي إحصاءات لاحقة غير مثبتة.","sources":[{"title":"Mohamed Salah: Egyptian king — where it all began","publisher":"BBC Sport","url":"https://www.bbc.co.uk/sport/football/articles/cx2xlk74llno"},{"title":"Mohamed Salah — Premier League statistics","publisher":"Premier League","url":"https://www.premierleague.com/players/5178/Mohamed-Salah/stats"},{"title":"Mohamed Salah — Liverpool FC historical profile","publisher":"Liverpool FC","url":"https://www.liverpoolfc.com/info/mohamed-salah"},{"title":"Premier League great Salah will leave lifetime of memories","publisher":"BBC Sport","url":"https://www.bbc.co.uk/sport/football/articles/c0r929g5p5eo"}],"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Mohamed_Salah_2018.jpg/800px-Mohamed_Salah_2018.jpg","imageAlt":"محمد صلاح خلال مسيرته الكروية","createdAt":"2026-10-21T00:00:00Z","updatedAt":"2026-10-21T08:00:00Z","status":"PUBLISHED","fallbackEvidence":"verified"},{"slug":"who-is-mohamed-salah-en","section":"people","language":"en","title":"Mohamed Salah: Biography, Career and Records","summary":"A sourced profile of Egyptian footballer Mohamed Salah, from his early years in Nagrig and El Mokawloon to his European career and achievements at Liverpool, with statistics dated and attributed.","body":"## Overview\n\nMohamed Salah Hamed Mahrous Ghaly, born on 15 June 1992, is an Egyptian footballer known for playing as a forward from the right, combining pace, movement and left-footed finishing. He began his senior career in Egypt before moving to Europe and becoming one of the most prominent Egyptian and African players of the modern era. Club and competition records document his career statistics, while independent journalism helps place those achievements in context.\n\n## Early Life and Beginnings\n\nSalah grew up in Nagrig, a village in Egypt’s Nile Delta. He joined the youth setup of Cairo-based El Mokawloon (Arab Contractors) at a young age, and the repeated journey from his village to training became part of accounts of his early development. He appeared for the senior team before moving to Swiss club Basel in 2012, where his performances in European competition drew wider attention. BBC Sport reporting on his background describes the youth centre in Nagrig and the support of family and early coaches; personal recollections should be treated as reported testimony rather than substitutes for official records.\n\n## Professional Career and European Breakthrough\n\nAt Basel, Salah played in domestic and European competitions and attracted interest after strong performances against English opposition. He joined Chelsea in 2014, then spent loan spells with Fiorentina and Roma in Italy before joining Roma permanently. The Italian period helped rebuild his standing in European football and showcased his development as both a scorer and creator.\n\nSalah joined Liverpool in June 2017. He scored 44 goals in all competitions in his first season according to the club’s historical profile, then helped Liverpool win the UEFA Champions League in 2019, followed by the FIFA Club World Cup and UEFA Super Cup. Liverpool won the Premier League in 2019–20 and 2024–25, and also secured the FA Cup and League Cup during his time at the club. Liverpool’s historical profile says his spell ended at the close of the 2025–26 season; this biography does not speculate about his next club.\n\n## Documented Honours and Records\n\nLiverpool’s historical profile published in 2026 records 442 appearances, 257 goals and 120 assists for the club across all competitions, and describes Salah as Liverpool’s leading Premier League goalscorer. The club also lists four Premier League Golden Boots, three PFA Players’ Player of the Year awards and three Football Writers’ Association Footballer of the Year awards. Statistics can differ depending on the publication date and whether they cover the league or all competitions, so each number should be read with its scope and date.\n\n## Sporting and Social Impact\n\nSalah’s influence extends beyond club and international football. He has become a widely recognised sporting figure in Egypt, the Arab world and among international football audiences. BBC Sport has reported on his connection to Nagrig, the aspirations he inspires among young players, and his wider place in discussions about identity and representation. Such accounts describe social impact rather than a single measurable statistic; opinions should be attributed to their speakers rather than presented as universal consensus.\n\n## How to Read His Career Accurately\n\nFor a specific goal or honour, prefer league and competition records and the club’s historical statistics over unsourced summaries. Distinguish league goals from goals in all competitions, team trophies from individual awards, and always note the date of the statistic. This profile summarises documented events through the end of the 2025–26 season and does not guess Salah’s next destination or later statistics that have not been established by sources.","sources":[{"title":"Mohamed Salah: Egyptian king — where it all began","publisher":"BBC Sport","url":"https://www.bbc.co.uk/sport/football/articles/cx2xlk74llno"},{"title":"Mohamed Salah — Premier League statistics","publisher":"Premier League","url":"https://www.premierleague.com/players/5178/Mohamed-Salah/stats"},{"title":"Mohamed Salah — Liverpool FC historical profile","publisher":"Liverpool FC","url":"https://www.liverpoolfc.com/info/mohamed-salah"},{"title":"Premier League great Salah will leave lifetime of memories","publisher":"BBC Sport","url":"https://www.bbc.co.uk/sport/football/articles/c0r929g5p5eo"}],"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Mohamed_Salah_2018.jpg/800px-Mohamed_Salah_2018.jpg","imageAlt":"Mohamed Salah during his football career","createdAt":"2026-10-21T00:00:00Z","updatedAt":"2026-10-21T08:00:00Z","status":"PUBLISHED","fallbackEvidence":"verified"}];

export function bundledArticleBySlug(slug:string, language:string){return BUNDLED_ARTICLES.find(x=>x.slug===slug&&x.language===language)||null}
export function bundledArticlesForSection(section:string, language:string, limit=24){return BUNDLED_ARTICLES.filter(x=>x.section===section&&x.language===language).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,Math.max(1,Math.min(50,limit)))}
/** Match only an exact short title to a reviewed long-form bundled article.
 * This deliberately avoids fuzzy entity matching so different people are never merged.
 */
export function bundledArticleForShortTitle(title:string, section:string, language:string){
  const normalize=(value:string)=>String(value||"").normalize("NFKC").toLocaleLowerCase()
    .replace(/[\u064B-\u065F\u0670\u0640]/g,"")
    .replace(/[’‘'".,!?()\[\]{}]/g,"")
    .replace(/\s+/g," ").trim();
  const wanted=normalize(title);
  if(!wanted||wanted.length<4||section!=="people")return null;
  const candidates=BUNDLED_ARTICLES.filter(x=>x.section===section&&x.language===language&&x.status==="PUBLISHED"&&x.fallbackEvidence==="verified"&&String(x.body||"").trim().length>=1200);
  return candidates.find(x=>{
    const candidate=normalize(x.title);
    if(candidate===wanted)return true;
    return candidate.startsWith(wanted) && /^[\s:：—–-]/u.test(candidate.slice(wanted.length));
  })||null;
}
export function bundledSearchArticles(query:string, language:string, limit=12){const terms=String(query||"").normalize("NFKC").toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(x=>x.length>1);if(!terms.length)return[];return BUNDLED_ARTICLES.filter(x=>x.language===language).map(x=>({...x,score:terms.reduce((n,t)=>n+((x.title+" "+x.summary).normalize("NFKC").toLowerCase().includes(t)?2:0)+(x.body.normalize("NFKC").toLowerCase().includes(t)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,Math.max(1,Math.min(24,limit)))}
